    ["01-7"] = {tips={{k="交通", text="스카이본 시작 지역입니다. 얼라이언스와 호드가 섬의 시작 퀘스트를 함께 하며, 섬을 떠날 때 진영이 나뉩니다.", s={{"스카이본 시작 지역입니다. 얼라이언스와 호드가 섬의 시작 퀘스트를 함께 하며, 섬을 떠날 때 진영이 나뉩니다.", {race={"Skyborne"}}}}}}, grind={[1]={mob="구름벌레 병사", note="센달 숲 동쪽의 구름벌레 떼. 수가 많고, 여왕을 잡으러 가는 길에 있습니다."}, [2]={mob="깡마른 우르세라", note="망루 서쪽 숲의 일반 몬스터. 한 마리씩 유인할 수 있습니다."}}, steps={[1]={npc="수집가 달리아", tgt="에일리 파하트"}, [2]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [3]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [4]={npc="팔로른 폴윈드", tgt="엘라트렐 페더라이트"}, [5]={hint="센달 숲에서 어린 벌드렌 8마리를 처치해야 합니다."}, [6]={hint="센달 숲에서 성가신 구름벌레 8마리를 처치해야 합니다."}, [7]={npc="팔로른 폴윈드", tgt="엘라트렐 페더라이트"}, [8]={npc="팔로른 폴윈드", tgt="엘라트렐 페더라이트"}, [9]={npc="매의 눈 할란", tgt="매의 눈 할란"}, [10]={npc="매의 눈 할란", tgt="매의 눈 할란"}, [11]={npc="미리알 미스트웨이크", tgt="미리알 미스트웨이크"}, [12]={hint="센달 숲 감시탑 꼭대기에서 뛰어내린 후 공중 걷기 능력을 사용해 낙하 속도를 늦춰야 합니다.", desc="구름벌레 여왕 쪽으로 뛰어내리면서 스카이본 종족 특성을 사용하세요."}, [13]={desc="아직 3레벨이 안 됐다면 탑 아래 센달 숲에서 Cirrusfly Soldier와 깡마른 우르세라를 잡아 3레벨까지 올리세요."}, [14]={hint="센달 숲에서 구름벌레 여왕을 처치해야 합니다."}, [15]={npc="팔로른 폴윈드", tgt="엘라트렐 페더라이트"}, [16]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [17]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [18]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [19]={npc="팔로른 폴윈드", tgt="팔로른 폴윈드"}, [20]={npc="낮의 탐구자 로리안", tgt="낮의 탐구자 로리안"}, [21]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [22]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [23]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [24]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [25]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [26]={npc="도리 브라이트위스퍼", tgt="도리 브라이트위스퍼"}, [27]={npc="바람구체자 보로", tgt="자이톤 실버윈드"}, [28]={npc="도리 브라이트위스퍼", tgt="타이리 파사이트"}, [29]={npc="아케리 더스크블레이드", tgt="아케리 더스크블레이드"}, [30]={npc="타이리 파사이트", tgt="바람구체자 보로"}, [31]={npc="타이리 파사이트", tgt="바람구체자 보로"}, [32]={npc="데스틴 스라이스포지드", tgt="수집가 달리아"}, [33]={npc="검귀 렌", tgt="검귀 렌"}, [34]={npc="얄라 윈드워처", tgt="얄라 윈드워처", desc="다음 몇 개 퀘스트를 하는 동안 바람석 덩어리를 모으세요. 조금 돌아가도 그만한 가치가 있습니다."}, [35]={npc="얄라 윈드워처", tgt="얄라 윈드워처"}, [36]={hint="센달 숲에 있는 지맥에서 지맥 읽기 종족 능력을 사용해야 합니다.", desc="지맥 옆에 서서 스카이본 종족 특성 \"지맥 읽