    ["02-10"] = {steps={[1]={npc="위즈뱅 크랭크토글", tgt="위즈뱅 크랭크토글"}, [2]={npc="그웨니스 블리레곤드", tgt="그웨니스 블리레곤드"}, [3]={node="아우버다인"}, [4]={hint="집게다리 6개를 모아 버즈박스 827에 넣어야 합니다.", desc="아우버다인 남쪽 해안에서 9~10레벨 게를 잡아 게 다리를 모으세요. 떠내려온 생물 퀘스트를 아직 받지 않았다면 11레벨 이후 부두를 다시 지날 때 받으세요."}, [5]={hint="아우버다인 바로 남쪽에 있는 떠내려온 바다 생물에게서 바다 생물 뼈를 회수한 후, 아우버다인에 있는 그웨니스 블리레곤드에게 가져가야 합니다."}, [6]={npc="버즈박스 827", npcObj=true}, [7]={npc="버즈박스 827", npcObj=true}, [8]={npc="그웨니스 블리레곤드", tgt="그웨니스 블리레곤드"}, [9]={npc="그웨니스 블리레곤드", tgt="그웨니스 블리레곤드"}, [10]={hint="다르나서스에 있는 엘라나리아에게 엘루니트 광석 상자 8개와 엘루라의 메달을 가져가야 합니다."}, [11]={npc="셀렐리안 화이트클로", tgt="셀렐리안 화이트클로"}, [12]={hint="아우버다인 서쪽 바다에 있는 바다 거북 유해에서 바다 거북 잔해를 회수한 후, 아우버다인에 있는 그웨니스 블리레곤드에게 돌아와 대화하십시오."}, [13]={hint="버즈박스 411 근처 깊은 바다에 있는 어둠의해안 트레샤돈에게서 트레샤돈의 눈 3개를 모아야 합니다."}, [14]={text="길을 따라 이 지점까지 달려가세요."}, [15]={npc="툰드리스 윈드위버", tgt="툰드리스 윈드위버"}, [16]={npc="툰드리스 윈드위버", tgt="툰드리스 윈드위버"}, [17]={npc="타나리운 트리텐더", tgt="타나리운 트리텐더"}, [18]={npc="테렌디스", tgt="테렌디스"}, [19]={text="길을 따라 이 지점까지 달려가세요."}, [20]={hint="광포한 엉겅퀴곰을 생포해 타나리운에게 데리고 와야 합니다."}, [21]={hint="아우버다인의 달빛야수 비석에 세나리온 달가루를 뿌려서 초승달발톱을 불러내야 합니다. 그런 다음 초승달발톱과 대면하여 그가 가진 육체와 정신의 힘을 얻어야 합니다."}, [22]={npc="아스테리온", tgt="아스테리온"}, [23]={npc="아스테리온", tgt="아스테리온"}, [24]={hint="바샬아란에 있는 아스테리온을 위해 그렐족 귀걸이 8개를 구해야 합니다."}, [25]={npc="아스테리온", tgt="아스테리온"}, [26]={npc="아스테리온", tgt="아스테리온"}, [27]={hint="고대 월장석 봉인을 찾아 바샬아란에 있는 아스테리온에게 가져가야 합니다."}, [28]={npc="아스테리온", tgt="아스테리온"}, [29]={npc="아스테리온", tgt="아스테리온"}, [30]={npc="타나리운 트리텐더", tgt="타나리운 트리텐더"}, [31]={npc="타나리운 트리텐더", tgt="타나리운 트리텐더"}, [32]={npc="파수꾼 글린다 날셰", tgt="파수꾼 글린다 날셰"}, [33]={npc="바리스라스 문셰이드", tgt="바리스라스 문셰이드"}, [34]={npc="현상수배: 먹구렁!", npcObj=true}, [35]={npc="그웨니스 블리레곤드", tgt="그웨니스 블리레곤드"}, [36]={hint="어둠의 해안의 동쪽 산맥을 따라 아우버다인 동쪽으로 가서 거대한 붉은 수정을 찾은 다음 아우버다인에 있는 파수꾼 글린다 날셰에게 보고해야 합니다."}, [37]={npc="파수꾼 티샤 문블레이드", tgt="파수꾼 티샤 문블레이드"}, [38]={hint="멸망한 아메스아란의 역사가 기록되어 있는 서판의 내용을 알아낸 다음 어둠의 해안에 있는 파수꾼 티샤 문블레이드에게 돌아가십시오."}, [39]={hint="아나야 돈러너의 영혼을 자유롭게 한 다음 그녀의 펜던트