    ["05-d1"] = {name="영주의 전당", entrance="아이언포지 27.63, 47.83", pickup="던 모로와 모단 호수를 지날 때 던전 입장 전 퀘스트를 먼저 받으세요. 입장 직전에 일부러 돌아올 필요는 없습니다. 스카이본은 {s:01-9}을 건너뜁니다. 처음 아이언포지에 갔을 때 동쪽 던 모로로 가서 대지선견자 파르센을 찾아 파르센의 경계, 싹부터 잘라내기, 지하 지도를 끝낸 뒤 아이언포지로 돌아오세요. 돌아가기 싫다면 구 아이언포지 침입은 건너뛰세요.", pickupS={{"던 모로와 모단 호수를 지날 때 던전 입장 전 퀘스트를 먼저 받으세요"}, {"입장 직전에 일부러 돌아올 필요는 없습니다"}, {"스카이본은 {s:01-9}을 건너뜁니다"}, {"처음 아이언포지에 갔을 때 동쪽 던 모로로 가서 대지선견자 파르센을 찾아 파르센의 경계, 싹부터 잘라내기, 지하 지도를 끝낸 뒤 아이언포지로 돌아오세요"}, {"돌아가기 싫다면 구 아이언포지 침입은 건너뛰세요"}}, steps={[1]={npc="검은무쇠 지도", npcObj=true, tag="던전 선행"}, [2]={npc="대지선견자 파르센", tgt="대지선견자 파르센", tag="던전 선행"}, [3]={npc="대지선견자 파르센", tgt="대지선견자 파르센"}, [4]={npc="아파드라 던월", tgt="아파드라 던월"}, [5]={npc="톰 필치", tgt="톰 필치"}, [6]={text="영주의 전당 입구"}, [7]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [8]={hint="영주의 전당에서 팔드림 앤빌마의 영혼에게 안식을 선사한 후 유령 수행원에게 가야 합니다."}, [9]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [10]={hint="분노한 원혼 15명과 고통받는 영혼 10명을 처치하고 앤빌마의 영혼을 안식에 들게 해야 합니다."}, [11]={hint="영주의 전당에서 드워프 가보 8개를 입수해야 합니다."}, [12]={hint="구 아이언포지 지하에 있는 영주의 전당에 진입해 드루겐 더지해머의 머리카락을 확보해야 합니다."}, [13]={npc="Treaty of Understanding", npcObj=true, desc="가방의 이해의 조약 아이템을 오른쪽 클릭해 퀘스트를 받으세요. 마지막 우두머리는 생명력 약 35%에서 공포를 겁니다. 먼저 졸개를 정리하고 우두머리를 이전 방으로 끌고 와서 잡으세요. 퀘스트를 받는 곳 옆에 레버가 있습니다. 당기면 문이 열려 곧장 밖으로 나갈 수 있습니다."}, [14]={npc="톰 필치", tgt="톰 필치"}, [15]={npc="아파드라 던월", tgt="아파드라 던월"}, [16]={npc="국왕 마그니 브론즈비어드", tgt="국왕 마그니 브론즈비어드"}, [17]={npc="국왕 마그니 브론즈비어드", tgt="국왕 마그니 브론즈비어드"}}},
