t="덴드리트 스타블레이즈", desc="사슴 10마리를 치료한 뒤 순간이동: 달의 숲으로 돌아가 퀘스트를 완료하세요."}, [110]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈", desc="퀘스트를 완료하면 해독 기술을 배웁니다."}, [111]={npc="마스렌길 베어워커", tgt="마스렌길 베어워커", desc="퀘스트를 완료해 독 치유를 배우세요. 나이트헤이븐에서 드루이드 전용 비행으로 루테란 마을에 간 뒤, 마을 안의 차원문으로 다르나서스에 들어가세요."}, [112]={npc="마스렌길 베어워커", tgt="마스렌길 베어워커"}, [113]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [114]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈", desc="엘룬아라 호수 바닥에서 제단 구슬을 찾으세요."}, [115]={hint="엘룬아라 호수에서 제단 구슬을 찾은 후 달의 숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.", desc="엘룬아라 호수 바닥에서 제단 구슬을 찾으세요."}, [116]={npc="타자리", tgt="타자리", desc="엘룬아라 호수 바닥에서 제단 구슬을 찾으세요."}, [117]={npc="타자리", tgt="타자리", desc="이상한 잠긴 상자 두 개에 각각 펜던트 반쪽이 들어 있습니다. 하나는 어둠의 해안 아우버다인 북쪽 바다 밑에, 다른 하나는 서부 몰락지대 북서쪽 해안 바다 밑에 있습니다."}, [118]={hint="민첩성의 바다 펜던트 반쪽과 인내의 바다 펜던트 반쪽을 찾아야 합니다. 달의 숲 주민들에게서 이 물건들이 있을 만한 위치에 대한 단서를 얻으십시오.", desc="나이트헤이븐에서 드루이드 전용 비행으로 루테란 마을에 간 뒤 아우버다인으로 비행해서, 북쪽 바다 밑의 잠긴 상자까지 헤엄쳐 가세요. 그다음 아우버다인에서 배를 타고 스톰윈드로 가서 감시의 언덕으로 비행하고, 북서쪽 해안으로 가서 잠수해 다른 잠긴 상자를 여세요."}, [119]={text="반쪽 두 개를 모으면 순간이동: 달의 숲으로 돌아가 레물로스의 제단 근처에서 펜던트를 하나로 합치세요."}, [120]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [121]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈", desc="퀘스트를 완료하면 바다표범 변신 기술을 배웁니다."}, [122]={npc="마스렌길 베어워커", tgt="마스렌길 베어워커", desc="퀘스트를 완료해 수중 변신을 배우세요. 나이트헤이븐에서 드루이드 전용 비행으로 루테란 마을에 간 뒤, 마을 안의 차원문으로 다르나서스에 들어가세요."}, [123]={text="다르나서스의 차원문으로 들어가 루테란 마을로 돌아가세요."}, [124]={nodeA="{a:702}", node="Rut'theran Village"}, [125]={to="아우버다인"}, [126]={hint="우두머리 엉겅퀴곰을 찾아서 처치해야 합니다."}, [127]={hint="아우버다인 달샘의 물로 빈 정화의 그릇을 채우십시오."}, [128]={hint="고대정령의 숲에 있는 오누에게 마시스트라 유물 6개를 가져가야 합니다."}, [129]={hint="고대정령의 숲에 있는 아르발을 위해 폭풍비늘일족 미르미돈 12명과 폭풍비늘일족 여마법사 8명, 폭풍비늘일족 전사 6명을 처치해야 합니다."}, [130]={hint="폭풍비늘 야수조련사를 찾아 처치한 후, 심연의 지배 마법막대를 가져와야 합니다."}, [131]={}}},
    ["05-d2"] = {name="로데론의 폐허", entrance="언더시티 72.41, 11.37", steps={[1]={text="멀리 떨어진 선택 퀘스트: 입구는 언더시티 위쪽 로데론 폐허에 있어 호드 지역을 지나야 합니다. 아우버다인에서 메네실 항구로 가는 배를 타고 사우스쇼어에서 내려 비행 지점을 열고, 북쪽으로 힐스브래드 구릉지와 은빛소나무 숲을 지나 티리스팔 숲에 가세요. 던전을 나오면 귀환석으로 스톰윈드에 돌아가 {s:02-14}으로 복귀하세요.", tag="선택사항"}, [2]={text="로데론의 폐허 입구"}, [3]={}, [4]={npc="피투성이 휘장", npcObj=true, desc="가방의 피투성이 휘장 아이템을 오른쪽 클릭해 퀘스트를 받으세요."}, [5]={hint="피투성이 휘장 10개를 모아 스톰윈드에 있는 장군 마커스 조나단에게 가져가야 합니다."}, [6]={npc="로데론의 문장", npcObj=true, desc="가방의 로데론의 문장 아이템을 오른쪽 클릭해 퀘스트를 받으세요."}, [7]={npc="Blood-Stained Parchment", npcObj=true, desc="가방의 Blood-Stained Parchment 아이템을 오른쪽 클릭해 퀘스트를 받으세요."}, [8]={}, [9]={npc="보육원 원장님 나이팅게일", tgt="보육원 원장님 나이팅게일"}, [10]={npc="귀부인 디나 케네디", tgt="귀부인 디나 케네디"}, [11]={npc="장군 마커스 조나단", tgt="장군 마커스 조나단"}}},
    ["02-14"] = {grind={[1]={mob="붉은마루일족 전사", note="레이크샤이어 북쪽의 놀 야영지. 일반 몬스터이고 비행 지점에서 가깝습니다."}, [2]={mob="검은바위부족 길잡이", note="영원의 호수 북동쪽 기슭의 검은바위부족 오크. 레벨이 더 알맞지만 그런트가 섞여 있으니 바깥쪽에서 유인하세요."}}, steps={[1]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [2]={npc="대여사제 로레나", tgt="대여사제 로레나", desc="스톰윈드에서 받아 아이언포지에서 완료하고 공포의 수호물을 배우세요."}, [3]={npc="대사제 로한", tgt="대사제 로한", desc="스톰윈드에서 받아 아이언포지에서 완료하고 공포의 수호물을 배우세요."}, [4]={text="아이언포지에서 깊은굴 지하철을 타고 스톰윈드로 돌아가세요."}, [5]={npc="대여사제 로레나", tgt="대여사제 로레나", desc="스톰윈드에서 받아 던 모로에서 완료하세요."}, [6]={npc="고위 여사제 밈스", tgt="고위 여사제 밈스", desc="스톰윈드에서 받아 던 모로에서 완료하세요."}, [7]={text="아이언포지로 돌아가 깊은굴 지하철을 타고 스톰윈드로 가세요."}, [8]={npc="제니아 캐논", tgt="제니아 캐논", desc="고독한 은둔자 선술집은 스톰윈드 마법사 지구에 있습니다."}, [9]={hint="제니아 캐논의 뒤에 있는 현신의 주문서와 속박의 상자를 집으십시오. 마법사의 성소에 있는 제이나에게 채워진 속박의 상자 3개를 가져가야 합니다.", desc="고독한 은둔자 선술집은 스톰윈드 마법사 지구에 있습니다."}, [10]={npc="제니아 캐논", tgt="제니아 캐논", desc="고독한 은둔자 선술집은 스톰윈드 마법사 지구에 있습니다."}, [11]={npc="제니아 캐논", tgt="제니아 캐논", desc="리넨 옷감 10개와 충만한 균열석 6개를 반납하세요. 균열석은 경매장에서 살 수 있습니다."}, [12]={npc="위니 라슨", tgt="위니 라슨", desc="리넨 옷감 10개와 충만한 균열석 6개를 반납하세요. 균열석은 경매장에서 살 수 있습니다."}, [13]={npc="위니 라슨", tgt="위니 라슨", desc="보상: 마나매듭 로브."}, [14]={npc="위니 라슨", tgt="위니 라슨", desc="보상: 마나매듭 로브."}, [15]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨"}, [16]={npc="현자 타카르", tgt="현자 타카르", desc="스톰윈드 항구에서 배를 타고 아우버다인으로 가서, 어둠의 해안을 따라 남쪽 잿빛 골짜기로 들어간 뒤 동쪽 몰샨 방벽으로 불모의 땅에 들어가 남쪽으로 내려가 타카르를 찾으세요. 크로스로드와 타우라조 야영지는 호드 거점이니 피해 가세요."}, [17]={npc="현자 타카르", tgt="현자 타카르"}, [18]={npc="현자 타카르", tgt="현자 타카르"}, [19]={hint="잿빛 골짜기에서 사랑나무를 찾아 스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 가져가야 합니다.", desc="먼저 나무 옆 몬스터를 처치한 뒤 그 세나리온 나무를 클릭해 사랑나무를 얻으세요."}, [20]={hint="목재 조각상을 찾아 스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 가져가야 합니다."}, [21]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨", desc="잿빛 골짜기를 끝내면 귀환석으로 스톰윈드에 돌아가세요. 귀환석이 재사용 대기 중이면 북쪽 아우버다인으로 돌아가 배를 타고 스톰윈드로 가세요."}, [22]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨"}, [23]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨", desc="대흑마법사 게이킨 옆의 소환진에서 사용하고 소환된 서큐버스를 쓰러뜨리세요."}, [24]={hint="사랑나무 줄기를 사용하여 서큐버스를 소환해 제압한 후, 어둠의 희생양 선술집에 있는 대흑마법사 게이킨에게 사랑나무 줄기를 가져가야 합니다.", desc="대흑마법사 게이킨 옆의 소환진에서 사용하고 소환된 서큐버스를 쓰러뜨리세요."}, [25]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨", desc="대흑마법사 게이킨 옆의 소환진에서 사용하고 소환된 서큐버스를 쓰러뜨리세요."}, [26]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨"}, [27]={hint="목재 조각상을 사용하여 인큐버스를 소환해 제압한 후, 어둠의 희생양 선술집에 있는 대흑마법사 게이킨에게 목재 조각상을 가져가야 합니다."}, [28]={npc="대흑마법사 게이킨", tgt="대흑마법사 게이킨"}, [29]={text="스톰윈드에서 엘윈 숲 큰길을 따라 동쪽으로 가세요. 먼저 아조라의 탑에서 테오크리투스에게 감시의 눈동자를 받으세요. 받은 뒤 다시 동쪽으로 가서 붉은마루 산맥 입구의 경비병 파커를 찾고, 큰길을 따라 레이크샤이어로 들어가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다, 붉은마루 산맥에 가기 전에 경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 멀록 지느러미 8개(침입자 멀록용)."}, [30]={npc="테오크리투스", tgt="테오크리투스"}, [31]={npc="경비병 파커", tgt="경비병 파커"}, [32]={to="Lakeshire", toA="{a:69}", tag="붉은마루 산맥에 가기 전에 경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 멀록 지느러미 8개(침입자 멀록용).", desc="아직 레이크샤이어 비행 지점을 열지 않았다면 스톰윈드에서 엘윈 숲 대로를 따라 동쪽으로 걸어 레이크샤이어까지 가세요."}, [33]={npc="경비병 파커", tgt="경비병 파커", desc="경비병 파커는 붉은마루 산맥 서쪽 큰길에서 엘윈 숲으로 이어지는 갈림길에 있습니다."}, [34]={npc="달시", tgt="달시"}, [35]={npc="악당 와일리", tgt="악당 와일리"}, [36]={npc="악당 와일리", tgt="악당 와일리"}, [37]={npc="항구주임 바렌", tgt="항구주임 바렌"}, [38]={npc="항구주임 바렌", tgt="항구주임 바렌", desc="멀록 지느러미는 경매장에서 살 수 있습니다. 8개를 모으면 사냥할 필요가 없습니다."}, [39]={npc="집정관 솔로몬", tgt="집정관 솔로몬"}, [40]={npc="베르너 오스구드", tgt="베르너 오스구드"}, [41]={npc="부관 펠던", tgt="부관 펠던"}, [42]={npc="부관 펠던", tgt="부관 펠던"}, [43]={npc="부관 펠던", tgt="부관 펠던"}, [44]={npc="루시우스", tgt="루시우스"}, [45]={npc="루시우스", tgt="루시우스", desc="앨더의 제재소 근처 상자에 자물쇠 따기를 사용하세요."}, [46]={hint="사용/수집: 루시우스의 금고", desc="앨더의 제재소 근처 상자에 자물쇠 따기를 사용하세요."}, [47]={npc="루시우스", tgt="루시우스", desc="앨더의 제재소 근처 상자에 자물쇠 따기를 사용하세요."}, [48]={npc="아란티르", tgt="아란티르", tag="선택사항"}, [49]={hint="호숫골에 있는 아란티르에게 네즈라의 뿔을 돌려줘야 합니다.", tag="선택사항"}, [50]={npc="아란티르", tgt="아란티르", tag="선택사항"}, [51]={nodeA="{a:69}", node="Lakeshire"}, [52]={npc="요루스 발리브루", tgt="요루스 발리브루", desc="레스밴 동굴은 붉은마루 산맥 북서쪽에 있으며 안에는 오우거가 있습니다."}, [53]={npc="요루스 발리브루", tgt="요루스 발리브루", desc="레스밴 동굴은 붉은마루 산맥 북서쪽에 있으며 안에는 오우거가 있습니다."}, [54]={npc="요루스 발리브루", tgt