    ["05-d7"] = {name="놈리건", entrance="던 모로 24.30, 39.80", pickup="잿빛 골짜기 (두 번째 방문) 경유 시 던전 전 퀘스트를 미리 받으세요. 던전 전에 따로 돌아올 필요가 없습니다.", pickupS={{"잿빛 골짜기 (두 번째 방문) 경유 시 던전 전 퀘스트를 미리 받으세요"}, {"던전 전에 따로 돌아올 필요가 없습니다"}}, steps={[1]={npc="각심 러스트피즐", tgt="각심 러스트피즐"}, [2]={npc="수사 세르노", tgt="수사 세르노"}, [3]={npc="소리없는 쇼니", tgt="소리없는 쇼니", tag="파티가 있을 때, 선택사항"}, [4]={npc="수석땜장이 오버스파크", tgt="수석땜장이 오버스파크", tag="파티가 있을 때, 선택사항"}, [5]={npc="땜장이왕 멕카토크", tgt="땜장이왕 멕카토크", tag="파티가 있을 때, 선택사항"}, [6]={npc="수석수리공 캐스트파이프", tgt="수석수리공 캐스트파이프", tag="파티가 있을 때, 선택사항"}, [7]={npc="클락몰트 스패너스판", tgt="클락몰트 스패너스판"}, [8]={npc="노아른", tgt="노아른", tag="선택사항, 파티가 있을 때"}, [9]={npc="오지 토글볼트", tgt="오지 토글볼트"}, [10]={npc="오지 토글볼트", tgt="오지 토글볼트", tag="선택사항, 파티가 있을 때"}, [11]={npc="메시엘", tgt="메시엘", tag="선택사항", desc="다르나서스에서 받으세요. 24레벨 필요: 아우버다인에서 루테란 마을로 비행해 차원문으로 도시에 들어가세요. 돌아가기 싫다면 던전 이후의 완료와 함께 건너뛰세요."}, [12]={text="메네실 항구에서 아이언포지로 비행한 뒤, 성문을 나가 던 모로 큰길을 따라 서쪽으로 놈리건까지 가세요."}, [13]={text="놈리건 입구"}, [14]={hint="스톰윈드에 있는 쇼니에게 기계장치 부속품 24개를 가져가야 합니다.", tag="파티가 있을 때, 선택사항", desc="기계 몬스터에게서 나옵니다. 스톰윈드로 돌아갈 때 완료하세요."}, [15]={npc="오지 토글볼트", tgt="오지 토글볼트", tag="선택사항, 파티가 있을 때"}, [16]={npc="수석땜장이 오버스파크", tgt="수석땜장이 오버스파크"}, [17]={npc="수석수리공 캐스트파이프", tgt="수석수리공 캐스트파이프"}, [18]={npc="클락몰트 스패너스판", tgt="클락몰트 스패너스판", tag="선택사항, 파티가 있을 때"}, [19]={npc="수석수리공 캐스트파이프", tgt="수석수리공 캐스트파이프", tag="선택사항, 파티가 있을 때"}, [20]={npc="수석땜장이 오버스파크", tgt="수석땜장이 오버스파크", tag="선택사항, 파티가 있을 때"}, [21]={npc="땜장이왕 멕카토크", tgt="땜장이왕 멕카토크", tag="선택사항, 파티가 있을 때"}, [22]={npc="클락몰트 스패너스판", tgt="클락몰트 스패너스판", tag="선택사항"}, [23]={to="Menethil Harbor", toA="{a:150}", desc="완료한 뒤 메네실 항구로 돌아가 힐스브래드 구릉지의 배를 타세요."}}},
