    ["03-27"] = {steps={[1]={npc="제니아 캐논", tgt="제니아 캐논", tag="경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 비취 1개. 나중에 먼지진흙 습지대 강력한 물건에 씁니다.", desc="먼지진흙 습지대의 타베사에게 완료하세요."}, [3]={npc="엘링 트리아스", tgt="엘링 트리아스"}, [4]={npc="엘링 트리아스", tgt="엘링 트리아스"}, [5]={npc="다셸 스톤피스트", tgt="다셸 스톤피스트"}, [6]={npc="다셸 스톤피스트", tgt="다셸 스톤피스트"}, [7]={hint="스톰윈드에 있는 다셸 스톤피스트와 싸워 이겨야 합니다."}, [8]={npc="다셸 스톤피스트", tgt="다셸 스톤피스트"}, [9]={npc="다셸 스톤피스트", tgt="다셸 스톤피스트"}, [10]={npc="엘링 트리아스", tgt="엘링 트리아스"}, [11]={npc="엘링 트리아스", tgt="엘링 트리아스"}, [12]={text="스톰윈드 드워프 지구로 가서 깊은굴 지하철을 타고 아이언포지로 가세요."}, [13]={npc="대석공 마블스텐", tgt="대석공 마블스텐"}, [14]={npc="대석공 마블스텐", tgt="대석공 마블스텐"}, [15]={npc="국왕 마그니 브론즈비어드", tgt="국왕 마그니 브론즈비어드"}, [16]={npc="게릭 본그립", tgt="게릭 본그립", tag="선택사항", desc="어둠의 해안에서 책: 힘의 저편을 주운 경우에만 완료하세요."}, [17]={npc="발굴조사단장 스톰파이크", tgt="발굴조사단장 스톰파이크"}, [18]={npc="발굴조사단장 스톰파이크", tgt="발굴조사단장 스톰파이크"}, [19]={npc="발굴조사단장 스톰파이크", tgt="발굴조사단장 스톰파이크"}, [20]={npc="발굴조사단장 스톰파이크", tgt="발굴조사단장 스톰파이크"}, [21]={npc="라고 블랙렌치", tgt="라고 블랙렌치"}, [22]={npc="스트라드 파선", tgt="스트라드 파선", desc="아이언포지에서 무법항으로 비행한 뒤 (스톰윈드에서 갈아탑니다) 배를 타고 톱니항으로 가세요."}, [23]={npc="스트라드 파선", tgt="스트라드 파선"}, [24]={npc="크롬 스타우트암", tgt="크롬 스타우트암", desc="톱니항에서 배를 타고 무법항으로 간 뒤 아이언포지로 비행하세요."}, [25]={npc="크롬 스타우트암", tgt="크롬 스타우트암"}, [26]={hint="아이언포지에 있는 크롬 스타우트암에게 곰팡이 슨 고서와 너덜너덜한 필사본을 가져가야 합니다.", desc="아이언포지에서 사우스쇼어로 비행하고, 돌아올 때는 다시 아이언포지로 비행하세요."}, [27]={npc="크롬 스타우트암", tgt="크롬 스타우트암"}, [28]={npc="크롬 스타우트암", tgt="크롬 스타우트암"}, [29]={hint="톱니항에 있는 스트라드 파선에게 복원된 고서와 정신 집중의 마법봉 3개를 가져가야 합니다.", desc="아이언포지에서 메네실 항구로 비행해 저습지 구간을 하세요."}, [30]={npc="스트라드 파선", tgt="스트라드 파선", desc="메네실 항구 남쪽 부두에서 배를 타고 테라모어로 가서 비행 지점을 연 뒤 톱니항으로 비행하세요. 아니면 메네실 항구에서 무법항으로 비행한 뒤 (아이언포지와 스톰윈드에서 갈아탑니다) 배를 타세요."}, [31]={npc="스트라드 파선", tgt="스트라드 파선", desc="스트라드 파선 근처 소환진에서 지옥사냥개를 소환해 쓰러뜨리세요."}, [32]={hint="비밀의 고서를 사용해 지옥사냥개를 소환해 제압한 다음 톱니항에 있는 스트라드 파선에게 사용한 고서를 돌려주어야 합니다.", desc="스트라드 파선 근처 소환진에서 지옥사냥개를 소환해 쓰러뜨리세요."}, [33]={npc="스트라드 파선", tgt="스트라드 파선", desc="스트라드 파선 근처 소환진에서 지옥사냥개를 소환해 쓰러뜨리세요."}, [34]={text="톱니항에서 불모의 땅 큰길을 따라 북쪽으로 가서 크로스로드를 지나 계속 북쪽으로 잿빛 골짜기에 들어간 뒤, 잿빛 골짜기 큰길을 따라 서쪽으로 아스트라나르 (34.41, 47.99)까지 가세요.", desc="크로스로드와 토막나무 주둔지는 호드 거점이니 돌아서 가세요. 비행 지도에 테라모어가 있으면 아스트라나르로 바로 비행할 수 있습니다(테라모어, 아우버다인 경유)."}, [35]={npc="클락몰트 스패너스판", tgt="클락몰트 스패너스판"}, [36]={npc="엘드룬 스톰브레이커", tgt="엘드룬 스톰브레이커", desc="바람의 부름: 아라시 고원에서 베이릭 썬더헤임을 찾으세요."}, [37]={to="Menethil Harbor", toA="{a:150}"}, [38]={npc="미크헤일", tgt="미크헤일"}, [39]={npc="미크헤일", tgt="미크헤일"}, [40]={hint="타포케 잔이 도망가기 전에 그를 제압한 다음 메네실에 있는 미크헤일에게 돌아가야 합니다."}, [41]={npc="미크헤일", tgt="미크헤일"}, [42]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [43]={npc="미크헤일", tgt="미크헤일"}, [44]={npc="미크헤일", tgt="미크헤일"}, [45]={npc="빈센트 하이얄", tgt="빈센트 하이얄", desc="같은 여관 안에 있습니다. 테라모어로 편지를 전달하세요."}, [46]={to="아우버다인", from="Menethil Harbor", fromA="{a:150}", desc="이 배는 도중에 사우스쇼어에 정박합니다. 아우버다인에서 내리세요."}}},
    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="파수꾼 멜리리아 프로스트섀도", tgt="파수꾼 멜리리아 프로스트섀도"}, [3]={npc="일리야나", tgt="일리야나"}, [4]={npc="펠투러스 화이트문", tgt="펠투러스 화이트문"}, [5]={text="길을 따라 이 지점까지 달려가세요."}, [6]={text="길을 따라 이 지점까지 달려가세요."}, [7]={hint="울부짖는 골짜기로 가서 멜탄드리스의 마법책을 찾아 읽어 본 다음 아에시나의 제단에 있는 파수꾼 멜리리아 프로스트섀도에게 돌아가십시오.", desc="동굴로 들어가 책을 가져오세요. 몬스터가 많이 끌려오기 쉽고, 희귀 몬스터가 있으면 더 어렵습니다."}, [8]={text="길을 따라 이 지점까지 달려가세요."}, [9]={hint="그늘덤불 나무현자에게서 유성 월장석을 빼앗아서 아스트라나르에 있는 펠투러스에게 가져가야 합니다."}, [10]={text="길을 따라 이 지점까지 달려가세요."}, [11]={hint="어둠의 터와 사티로스나르에 갇혀 있는 명가의 영혼들을 구출하고 마에스트라 주둔지에 있는 수호자 델그렌에게 돌아가십시오."}, [12]={npc="아닐리아", tgt="아닐리아"}, [13]={npc="아닐리아", tgt="아닐리아"}, [14]={hint="겔타리스를 처치하고 아에시나의 제단에 있는 일리야나에게 세나리우스의 가지를 돌려줘야 합니다."}, [15]={npc="케이네스 스틸윈드", tgt="케이네스 스틸윈드"}, [16]={npc="마세라 어텀문", tgt="마세라 어텀문"}, [17]={hint="숲의 노래 서쪽에 있는 사티르나르 악마들 사이에서 마세라 어텀문의 남편 쿠로델의 흔적을 찾은 후, 마세라에게 가서 보고해야 합니다."}, [18]={npc="마세라 어텀문", tgt="마세라 어텀문"}, [19]={nodeA="{a:3137}", node="Talrendis Point", desc="숲의 노래에서 큰길을 따라 동쪽으로 아즈샤라에 들어가세요. 야영지는 입구 바로 옆에 있습니다."}, [20]={to="Astranaar", toA="{a:415}"}, [21]={npc="펠투러스 화이트문", tgt="펠투러스 화이트문"}, [22]={npc="파수꾼 멜리리아 프로스트섀도", tgt="파수꾼 멜리리아 프로스트섀도"}, [23]={npc="파수꾼 멜리리아 프로스트섀도", tgt="파수꾼 멜리리아 프로스트섀도", tag="선택사항"}, [24]={npc="일리야나", tgt="일리야나"}, [25]={npc="수호자 델그렌", tgt="수호자 델그렌"}}},
    ["03-29"] = {grind={[1]={mob="소금바위 큰눈바실리스크", note="소금 평원 남쪽 끝의 일반 몬스터. 경주 중의 충돌의 바실리스크와 같은 구역입니다."}, [2]={mob="소금바위 수정바실리스크", note="큰눈바실리스크와 섞여 있습니다. 수가 더 많고 레벨은 조금 낮습니다."}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="선택사항", desc="다르나서스 구간은 경험치가 적습니다. 서두르면 건너뛰세요."}, [2]={text="루테란 마을의 차원문으로 들어가 다르나서스로 가세요.", tag="선택사항"}, [3]={npc="신텔 블레이드위버", tgt="신텔 블레이드위버", tag="선택사항"}, [4]={npc="신텔 블레이드위버", tgt="신텔 블레이드위버", tag="선택사항"}, [5]={hint="벨린데의 상자에서 일지를 찾은 다음 열쇠와 함께 다르나서스에 있는 신텔 블레이드위버에게 돌려주어야 합니다.", tag="선택사항"}, [6]={npc="신텔 블레이드위버", tgt="신텔 블레이드위버", tag="선택사항"}, [7]={npc="신텔 블레이드위버", tgt="신텔 블레이드위버", tag="선택사항"}, [8]={text="다르나서스의 차원문으로 들어가 루테란 마을로 돌아가세요.", tag="선택사항"}, [9]={text="다르나서스 선택 퀘스트를 했다면 루테란 마을에서 톱니항으로 비행하고 (아우버다인과 탈렌드리스 초소에서 갈아탑니다), 건너뛰었다면 아스트라나르에서 비행하세요 (탈렌드리스 초소에서 갈아탑니다). 큰길을 따라 남쪽으로 가서 타우라조 야영지를 피하고, 구름 승강장을 타고 버섯구름 봉우리로 내려가세요. 두 지점을 열지 않았을 때만 몰샨 방벽으로 가세요."}, [10]={text="길을 따라 이 지점까지 달려가세요."}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [13]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [14]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [15]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [16]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [17]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [18]={npc="포직", tgt="포직"}, [19]={npc="경주로관리인 제린", tgt="경주로관리인 제린"}, [20]={hint="소금 평원에 있는 포직을 위해 가벼운 독수리 뼈 10개를 구해야 합니다."}, [21]={hint="소금 평원에 있는 경주로관리인 제린을 위해 소금바위 바실리스크 10 마리, 소금바위 수정바실리스크 10 마리 및 소금바위 큰눈바실리스크 6 마리를 처치해야 합니다."}, [22]={hint="소금 평원에 있는 위즐 브라스볼츠에게 단단한 거북 등껍질 9개를 가져가야 합니다."}, [23]={hint="소금 평원의 크레이블 콜비어드에게 로켓 자동차 부품 30개를 가져가야 합니다."}, [24]={hint="소금 평원에 있는 피즐 브라스볼츠에게 소금기 있는 전갈 독 6개를 가져가야 합니다."}, [25]={npc="포직", tgt="포직"}, [26]={npc="경주로관리인 제린", tgt="경주로관리인 제린"}, [27]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [28]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [29]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [30]={desc="소금 평원을 떠나기 전에 아직 35레벨이 안 됐다면 경주장 남쪽에서 소금바위 큰눈바실리스크와 소금바위 수정바실리스크를 잡아 35레벨까지 올리세요."}, [31]={text="소금 평원에서 큰길을 따라 남쪽 타나리스로 들어가 가젯잔에서 비행 지점을 연 뒤 귀환석을 쓰세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [32]={nodeA="{a:976}", node="Gadgetzan"}, [33]={}}},
    ["03-30"] = {name="아라시 고원", grind={[1]={mob="마른수염 코볼트", note="마른수염 골짜기 입구 일대의 일반 몬스터. 함정에 빠진 공주를 끝내는 곳 바로 옆입니다."}, [2]={mob="마른수염일족 채굴꾼", note="골짜기 깊숙한 곳의 수정 옆. 레벨이 더 알맞습니다."}, [3]={mob="돌주먹일족 투사", note="돌주먹 소굴 외곽의 오우거. 마법봉을 얻으러 가는 길에 있습니다."}, [4]={mob="마른나무껍질부족 어둠사냥꾼", note="남동쪽의 마른나무껍질 마을. 마법 재료 구하기와 같은 트롤입니다."}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="임시 주둔지를 열지 않았다면 메네실 항구로 날아가 습지대 큰길을 따라 북동쪽으로 간 뒤, 탄돌 교각을 건너 아라시 고원으로 들어가 큰길을 따라 임시 주둔지까지 가세요."}, [2]={npc="부대장 나이얼스", tgt="부대장 나이얼스"}, [3]={npc="현상수배 전단", npcObj=true, tag="파티가 있을 때, 선택사항"}, [4]={npc="현상수배 전단", npcObj=true, tag="파티가 있을 때, 선택사항", desc="오토와 팰컨크레스트 경은 38, 40레벨 정예입니다."}, [5]={npc="스쿼토", tgt="스쿼토"}, [6]={npc="견습마법사 크리텐", tgt="견습마법사 크리텐"}, [7]={npc="미즈라엘의 결정", npcObj=true}, [8]={hint="미즈라엘의 결정 파편을 12개 모아서 마른수염 골짜기에 있는 오색 결정에 가져가야 합니다."}, [9]={npc="오색 결정", npcObj=true}, [10]={desc="36레벨의 약 4분의 3까지 올리세요; 바로 여기 마른수염 골짜기에서 마른수염 코볼트와 마른수염일족 채굴꾼을 잡으세요."}, [11]={npc="오색 결정", npcObj=true, desc="동부 봉인석은 서쪽으로 가는 길에 있으니 먼저 처리하세요; 외부 봉인석은 임시 주둔지로 가는 길에 처리하세요."}, [12]={npc="쿠에", tgt="쿠에"}, [13]={npc="쿠에", tgt="쿠에"}, [14]={hint="포세이큰 급사를 찾아서 봉인된 서류를 고셰크 농장 근처에 있는 쿠에에게 가져가야 합니다.", desc="포세이큰 급사는 고셰크 농장 일대의 큰길을 순찰합니다. 보이면 처치하고 봉인된 서류를 챙기세요."}, [15]={hint="임시 주둔지에 있는 견습마법사 크리텐에게 마른나무껍질부족 어금니 10개, 마른나무껍질부족 약초 주머니 4개, 어둠사냥꾼 나이프 1개를 가져가야 합니다.", desc="순찰하는 포세이큰 급사를 조심하세요."}, [16]={npc="견습마법사 크리텐", tgt="견습마법사 크리텐"}, [17]={npc="부대장 나이얼스", tgt="부대장 나이얼스", desc="강물터 파홀드 성채의 디마르 브랜트에게 완료하세요. 다음 지점에서 가게 됩니다."}, [18]={npc="스쿼토", tgt="스쿼토"}, [19]={desc="한파의 코르그레쉬 (39레벨)를 잡기 전에 아직 37레벨이 안 됐다면, 돌주먹 소굴 밖에서 돌주먹일족 투사를 잡거나 동쪽 마른나무껍질 마을에서 마른나무껍질 트롤을 잡아 37레벨까지 올리세요."}, [20]={hint="트렐레인의 마법지팡이를 찾아 임시 주둔지에 있는 스쿼토에게 가져가야 합니다."}, [21]={npc="쿠에", tgt="쿠에"}, [22]={npc="쿠에", tgt="쿠에"}, [23]={npc="키넬로리", tgt="키넬로리"}, [24]={npc="키넬로리", tgt="키넬로리"}, [25]={hint="키넬로리가 쿠에에게 돌아갈 때까지 보호해야 합니다.", desc="호위 퀘스트입니다. 키넬로리를 따라가세요. 도중에 매복이 있습니다."}, [26]={npc="쿠에", tgt="쿠에"}, [27]={npc="쿠에", tgt="쿠에"}, [28]={npc="스쿼토", tgt="스쿼토"}, [29]={npc="스쿼토", tgt="스쿼토", tag="파티가 있을 때, 선택사항"}, [30]={hint="서부 봉인석, 동부 봉인석, 외부 봉인석에서 각각 불타는 열쇠, 용마루장식 열쇠, 천둥 열쇠를 구해야 합니다."}, [31]={hint="비밀결사대 강도 10명과 비밀결사대 용병 6명을 처치해야 합니다."}, [32]={npc="부대장 나이얼스", tgt="부대장 나이얼스"}, [33]={npc="부대장 나이얼스", tgt="부대장 나이얼스", tag="파티가 있을 때, 선택사항"}, [34]={npc="내부 봉인석", npcObj=true}, [35]={hint="마레즈를 처치하고 그 증거로 그녀의 머리카락을 임시 주둔지에 있는 부대장 나이얼스에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [36]={hint="오토와 팰컨크레스트를 처치하고 그 증거로 머리카락을 임시 주둔지에 있는 부대장 나이얼스에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [37]={hint="임시 주둔지에 있는 부대장 나이얼스에게 스트롬가드 휘장 15개를 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [38]={hint="푸른색 마노를 찾아서 임시 주둔지에 있는 견습마법사 크리텐에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [39]={npc="부대장 나이얼스", tgt="부대장 나이얼스", tag="파티가 있을 때, 선택사항"}, [40]={npc="부대장 나이얼스", tgt="부대장 나이얼스", tag="파티가 있을 때, 선택사항"}, [41]={npc="부대장 나이얼스", tgt="부대장 나이얼스", tag="파티가 있을 때, 선택사항"}, [42]={npc="견습마법사 크리텐", tgt="견습마법사 크리텐", tag="파티가 있을 때, 선택사항"}, [43]={npc="견습마법사 크리텐", tgt="견습마법사 크리텐"}, [44]={npc="스쿼토", tgt="스쿼토"}, [45]={npc="스쿼토", tgt="스쿼토"}, [46]={hint="트렐레인의 부적, 트렐레인의 수정구, 트렐레인의 붉은 마노를 찾아 임시 주둔지에 있는 스쿼토에게 가져가야 합니다.", tag="나중에 지나갈 때 진행"}, [47]={npc="스쿼토", tgt="스쿼토"}, [48]={npc="스쿼토", tgt="스쿼토"}, [49]={hint="북부습곡 장원에서 비밀결사대 제복을 훔쳐 스트롬가드 요새에 잠입해야 합니다.", desc="아라시 고원 북부습곡 장원에서 비밀결사대 제복을 훔치세요."}, [50]={npc="비밀결사대 사물함", npcObj=true}, [51]={npc="비밀결사대 사물함", npcObj=true}, [52]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal."}, [53]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러"}, [54]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러"}, [55]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal."}, [56]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러"}, [57]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러"}, [58]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor."}, [59]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼"}, [60]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임"}, [61]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="파티가 있을 때, 선택사항", desc="가시덩굴 우리(불모의 땅 남쪽의 던전)를 돌아야 하니 파티를 구한 뒤 진행하세요. 후속 퀘스트 폭풍과 대지와 불도 함께 건너뛰세요."}, [62]={hint="가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 관한 정보를 수집해야 합니다.", tag="파티가 있을 때, 선택사항"}, [63]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="파티가 있을 때, 선택사항", desc="베이릭 썬더헤임은 아이언포지 (47.10, 13.79)에서도 만날 수 있습니다."}, [64]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="선택사항", desc="뒤틀린 토템 네 종류는 먼지진흙 습지대, 황야의 땅, 슬픔의 늪, 잊혀진 땅의 몬스터에게서 나오니 이후 몇 지점을 지나며 모으세요. 마지막으로 아이언포지의 베이릭 썬더헤임에게 완료하세요."}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="핀 오델릭", tgt="핀 오델릭"}, [67]={npc="집정관 헨리 말레브", tgt="집정관 헨리 말레브"}, [68]={desc="귀환석이 대기 중이면 사우스쇼어에서 아이언포지로 날아가 깊은굴 지하철을 타고 스톰윈드로 돌아가세요."}}},
    ["05-d8"] = {name="붉은십자군 수도원", entrance="티리스팔 숲 82.60, 33.80", pickup="저습지 (두 번째 방문) 경유 시 던전 전 퀘스트를 미리 받으세요. 던전 전에 따로 돌아올 필요가 없습니다.", pickupS={{"저습지 (두 번째 방문) 경유 시 던전 전 퀘스트를 미리 받으세요"}, {"던전 전에 따로 돌아올 필요가 없습니다"}}, steps={[1]={npc="사서 메이 페일더스트", tgt="사서 메이 페일더스트"}, [2]={to="Southshore", toA="{a:271}", desc="아이언포지에서 갈아탑니다."}, [3]={text="사우스쇼어에서 북쪽으로 힐스브래드 구릉지와 알터랙 산맥을 지나 서부 역병지대로 들어간 뒤 서쪽 티리스팔 숲으로 가서, 길을 따라 북동쪽 모서리의 붉은십자군 수도원으로 가세요."}, [4]={text="붉은십자군 수도원 입구"}, [5]={}, [6]={text="스톰윈드 드워프 지구로 가서 깊은굴 지하철을 타고 아이언포지로 가세요."}, [7]={npc="사서 메이 페일더스트", tgt="사서 메이 페일더스트", tag="선택사항"}}},
    ["03-31"] = {tips={{k="提醒", text="지도 중앙의 로그마는 호드 마을이니 가까이 가지 마세요.", s={{"지도 중앙의 로그마는 호드 마을이니 가까이 가지 마세요"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="강물터에 가기 전에 경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 견고한 숫돌 8개(가장 날카로운 검용).", desc="파홀드 성채에는 아직 비행 지점이 없으니, 처음에는 레이크샤이어에서 큰길을 따라 동쪽으로 걸어 강물터 서쪽 입구로 들어가세요."}, [2]={text="붉은마루 산맥 동쪽 입구를 지나면 뾰족털 언덕입니다. 입구 일대의 36-38레벨 놀은 아프게 때립니다.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [3]={npc="정찰병 볼레인", tgt="정찰병 볼레인"}, [4]={npc="세드릭 달튼", tgt="세드릭 달튼"}, [5]={npc="세드릭 달튼", tgt="세드릭 달튼"}, [6]={npc="세드릭 달튼", tgt="세드릭 달튼"}, [7]={npc="세드릭 달튼", tgt="세드릭 달튼", tag="선택사항, 파티가 있을 때", desc="스나글은 40레벨 정예입니다. 이길 수 없으면 건너뛰세요."}, [8]={npc="컬리", tgt="컬리"}, [9]={npc="핼리건 터너", tgt="핼리건 터너"}, [10]={npc="핼리건 터너", tgt="핼리건 터너"}, [11]={npc="헐리", tgt="헐리"}, [12]={npc="헐리", tgt="헐리"}, [13]={hint="헐리와 함께 컬리를 구하러 가야 합니다.", desc="헐리를 따라가 컬리를 구하세요."}, [14]={hint="남부 감시터의 세드릭 달튼이 부탁한 대로 붉은마루일족 비술사 8명과 붉은마루일족 덫사냥꾼 8명, 붉은마루일족 투사 6명을 처치해야 합니다."}, [15]={hint="뾰족털 언덕의 놀 야영지에서 톱날 8개를 회수한 후, 제재소에 있는 핼리건 터너에게 가져가야 합니다.", desc="톱날은 놀 야영지 바닥에 흩어져 있습니다."}, [16]={hint="뾰족털 언덕에서 스나글을 찾아 처치한 뒤, 그 주둥이를 남부 감시터에 있는 세드릭 달튼에게 가져가야 합니다.", tag="선택사항, 파티가 있을 때", desc="스나글은 40레벨 정예입니다. 이길 수 없으면 건너뛰세요."}, [17]={npc="핼리건 터너", tgt="핼리건 터너"}, [18]={npc="핼리건 터너", tgt="핼리건 터너"}, [19]={npc="엘리노어 홈스비", tgt="엘리노어 홈스비"}, [20]={npc="로비 홈스비", tgt="로비 홈스비"}, [21]={npc="감시자 프레더릭스", tgt="감시자 프레더릭스"}, [22]={npc="세드릭 달튼", tgt="세드릭 달튼"}, [23]={npc="세드릭 달튼", tgt="세드릭 달튼", tag="선택사항"}, [24]={npc="벤지 휠러", tgt="벤지 휠러"}, [25]={hint="휠러의 농가 근처 강가에서 진흙아가미 예언자 8마리와 진흙아가미 전사 8마리를 처치해야 합니다."}, [26]={hint="거대한 가재 껍데기 4개, 신선한 거름 4개, 진흙지느러미 멀록 머리 8개를 모아 핼리건 터너에게 전달해야 합니다.", desc="진흙지느러미 멀록 머리는 민물의 악귀와 함께 잡고, 이어서 북쪽에서 거대한 가재를 잡고 신선한 비료를 주우세요."}, [27]={hint="강가 어딘가에서 멀록 주위에 있는 로비의 모자를 찾아야 합니다.", desc="진흙지느러미 멀록 야영지에서 모자를 찾으세요."}, [28]={nodeA="{a:16724}", node="Farholde Keep"}, [29]={npc="디마르 브랜트", tgt="디마르 브랜트"}, [30]={npc="디마르 브랜트", tgt="디마르 브랜트"}, [31]={npc="디마르 브랜트", tgt="디마르 브랜트"}, [32]={npc="디마르 브랜트", tgt="디마