    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="순찰대장 소리갈", tgt="순찰대장 소리갈"}, [3]={text="다크샤이어에서 동쪽 죽음의 고개를 지나 슬픔의 늪으로 들어가세요."}, [4]={npc="파수병 비그스", tgt="파수병 비그스"}, [5]={hint="무법항에 있는 크라젝에게 꿈가루 10줌을 가져가야 합니다. 꿈가루는 슬픔의 늪에 있는 용들에게서 얻을 수 있습니다."}, [6]={hint="새끼 톱니악어 8마리, 늪그물거미 10마리, 늪지재규어 10마리를 처치한 다음 슬픔의 늪에 있는 파수병 비그스에게 돌아가야 합니다."}, [7]={npc="파수병 비그스", tgt="파수병 비그스"}, [8]={npc="파수병 비그스", tgt="파수병 비그스"}, [9]={npc="노보루의 곤봉", npcObj=true, tag="선택사항", desc="가방의 노보루의 곤봉 아이템을 오른쪽 클릭해 퀘스트를 받으세요. 곤봉잡이 노보루를 잡아 회색 곤봉을 얻고 오른쪽 클릭해 퀘스트를 시작하세요."}, [10]={npc="막투르", tgt="막투르", tag="선택사항"}, [11]={npc="막투르", tgt="막투르"}, [12]={hint="슬픔의 늪의 피난처에 있는 막투르에게 드레니시스트 수정 6개를 가져가야 합니다."}, [13]={hint="드레노어 성역에서 마법사들의 재료가 들어 있는 짐마차 상자를 찾아 파수병 비그스에게 가져가야 합니다."}, [14]={npc="갈렌 굿워드", tgt="갈렌 굿워드"}, [15]={hint="갈렌이 위험에서 벗어나도록 호위한 다음 슬픔의 늪에 있는 그의 야영지를 찾아 갈렌의 금고를 열어야 합니다.", tag="호위", desc="갈렌을 따라 드레노어 성역(드레노어 난민의 야영지)을 나가세요. 길에서 몬스터가 그를 공격하니 보호하세요. 호위가 끝나면 그의 야영지로 가서 금고를 여세요."}, [16]={npc="갈렌의 금고", npcObj=true}, [17]={npc="막투르", tgt="막투르"}, [18]={npc="파수병 비그스", tgt="파수병 비그스"}, [19]={npc="파수병 비그스", tgt="파수병 비그스"}, [20]={text="길을 따라 이 지점까지 달려가세요."}, [21]={hint="슬픔의 늪에 있는 파수병 비그스에게 볕에 말린 유목 8개를 가져가야 합니다."}, [22]={hint="스톰윈드에 있는 브로한 캐스크벨리가 아탈학카르 신전을 찾아 달라고 부탁했습니다.", desc="가라앉은 사원에 다가가면 완료됩니다."}, [23]={npc="파수병 비그스", tgt="파수병 비그스"}, [24]={npc="파수병 비그스", tgt="파수병 비그스"}, [25]={text="슬픔의 늪 남쪽에서 저주받은 땅으로 들어가 길을 따라 남쪽 네더가드 요새까지 가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [26]={npc="병참장교 룬겔츠", tgt="병참장교 룬겔츠"}, [27]={nodeA="{a:1438}", node="Nethergarde Keep"}}},
    ["03-37"] = {tips={{k="提醒", text="지도 중앙의 로그마는 호드 마을이니 가까이 가지 마세요.", s={{"지도 중앙의 로그마는 호드 마을이니 가까이 가지 마세요"}}}}, steps={[1]={to="Farholde Keep", toA="{a:16724}", tag="강물터에 가기 전에 경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 마법 옷감 20개(압박 붕대용).", desc="다크샤이어와 레이크샤이어에서 갈아탑니다."}, [2]={npc="디마르 브랜트", tgt="디마르 브랜트"}, [3]={npc="디마르 브랜트", tgt="디마르 브랜트"}, [4]={npc="디마르 브랜트", tgt="디마르 브랜트", desc="먼저 드롭으로 시작되는 야전사령관의 기록를 완료해야 받을 수 있습니다."}, [5]={npc="애시 앰버홀", tgt="애시 앰버홀"}, [6]={npc="베르트랑 아이언브로우", tgt="베르트랑 아이언브로우"}, [7]={npc="수사 로울리", tgt="수사 로울리", tag="선택사항, 재료가 모이면 진행", desc="마법 옷감 20개가 필요합니다. 경매장에서 살 수 있습니다. 없으면 건너뛰세요."}, [8]={npc="수사 로울리", tgt="수사 로울리", tag="선택사항"}, [9]={npc="수사 로울리", tgt="수사 로울리"}, [10]={hint="수사 로울리를 위해 부상당한 병사 3명에게 붕대를 감아줘야 합니다.", desc="부상당한 병사는 수사 로울리 바로 옆에 있습니다."}, [11]={npc="수사 로울리", tgt="수사 로울리"}, [12]={npc="수사 로울리", tgt="수사 로울리"}, [13]={npc="수녀 롤랜드", tgt="수녀 롤랜드"}, [14]={npc="테사 돈브라이트", tgt="테사 돈브라이트"}, [15]={hint="파홀드 성채의 테사 돈브라이트를 위한 신선한 사과 6개를 모아야 합니다.", desc="신선한 사과는 파홀드 성채 근처 과수 아래에 있습니다."}, [16]={npc="테사 돈브라이트", tgt="테사 돈브라이트"}, [17]={npc="테사 돈브라이트", tgt="테사 돈브라이트"}, [18]={hint="파홀드 성채의 테사 돈브라이트를 위한 코요테 모피 3개를 모아야 합니다."}, [19]={npc="테사 돈브라이트", tgt="테사 돈브라이트"}, [20]={npc="테사 돈브라이트", tgt="테사 돈브라이트"}, [21]={npc="감시자 코넬리우스", tgt="감시자 코넬리우스"}, [22]={text="테랄의 감시터에서 서쪽으로 가서, 햇살숲 남쪽을 지나 황혼의 장막 앞의 하사관 리프탄에게 가세요. 터너의 벌목지를 지날 때 목재를 주우세요."}, [23]={hint="터너의 벌목지에서 목재 묶음 10개를 획득해 파홀드 성채에 있는 베르트랑 아이언브로우에게 전달해야 합니다.", desc="목재 더미는 터너의 벌목지에 있습니다."}, [24]={npc="하사관 리프탄", tgt="하사관 리프탄"}, [25]={npc="하사관 리프탄", tgt="하사관 리프탄"}, [26]={npc="하사관 리프탄", tgt="하사관 리프탄"}, [27]={npc="하사관 리프탄", tgt="하사관 리프탄"}, [28]={hint="황혼의 장막에 있는 도관에서 황혼의 노예를 소환한 뒤, 앰버홀의 영혼석으로 사로잡아야 합니다.", desc="황혼의 장막의 유도 장치에서 황혼의 노예를 소환하고 영혼석으로 붙잡으세요."}, [29]={npc="치안대장 라이언", tgt="치안대장 라이언"}, [30]={npc="치안대장 라이언", tgt="치안대장 라이언"}, [31]={hint="하사관 리프탄을 위해 황혼의 장막에서 파홀드 정찰병 5명을 구출해야 합니다.", desc="정찰병은 황혼의 장막 곳곳에 갇혀 있습니다."}, [32]={hint="하사관 리프탄을 위해 황혼의 장막에서 황혼의 광신자 8명과 황혼의 타락자 8명, 황혼의 용사 8명을 처치해야 합니다."}, [33]={hint="하