    ["03-38"] = {steps={[1]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드"}, [2]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드", desc="격투의 섬 투기장에서 상대 네 무리를 연달아 쓰러뜨리세요."}, [3]={hint="싸움꾼 윌을 꺾고 격투의 섬에 있는 클라녹 맥클라우드과 대화하십시오.", desc="격투의 섬 투기장에서 상대 네 무리를 연달아 쓰러뜨리세요."}, [4]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드", desc="격투의 섬 투기장에서 상대 네 무리를 연달아 쓰러뜨리세요."}, [5]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드"}, [6]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="아카나의 로브가 필요합니다. 재봉사에게 부탁하거나 경매장에서 사세요."}, [7]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="아카나의 로브가 필요합니다. 재봉사에게 부탁하거나 경매장에서 사세요."}, [8]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="금괴 ×1: 경매장에서 살 수 있습니다."}, [9]={hint="가시덤불 골짜기에 있는 시즈크 굿스티치에게 금괴 하나를 가져가야 합니다."}, [10]={npc="시즈크 굿스티치", tgt="시즈크 굿스티치", desc="톱니항에서 배를 타고 무법항으로 가세요."}, [11]={npc="시즈크 굿스티치", tgt="시즈크 굿스티치"}, [12]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="무법항에서 배를 타고 톱니항으로 돌아가세요."}, [13]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더"}, [14]={hint="불모의 땅에 있는 미네라 보이드렌더에게 서릿발분노의 사티로스 피 10병과 하급 지옥정령석 1개를 가져가야 합니다."}, [15]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더"}, [16]={npc="시즈크 굿스티치", tgt="시즈크 굿스티치", desc="톱니항에서 배를 타고 무법항으로 가세요."}, [17]={npc="시즈크 굿스티치", tgt="시즈크 굿스티치"}, [18]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="무법항에서 배를 타고 톱니항으로 돌아가세요."}, [19]={hint="불모의 땅에 있는 미네라 보이드렌더에게 고급 금빛 실타래와 이글거리는 석탄 2개, 그리고 영혼의 조각 1개를 가져가야 합니다.", desc="아라시 구간: 톱니항에서 배를 타고 무법항으로 가서 임시 주둔지로 비행하세요 (스톰윈드와 아이언포지에서 갈아탑니다). 돌아올 때는 반대로 가세요."}, [20]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더"}, [21]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="보상: 마법의 황금 혈로브."}, [22]={hint="미레나 보이드렌드가 로브를 완성할 때까지 기다린 다음 그녀와 다시 대화하십시오.", desc="보상: 마법의 황금 혈로브."}, [23]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", desc="보상: 마법의 황금 혈로브."}, [24]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더"}, [25]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더"}, [26]={npc="수행사제 위툴라", tgt="수행사제 위툴라", desc="지옥사냥개 조각입니다. 이 퀘스트와 지옥불정령의 영혼 중 하나만 고르세요."}, [27]={npc="수행사제 마가즈", tgt="수행사제 마가즈", tag="선택사항", desc="지옥불정령 조각입니다. 이 퀘스트와 지옥사냥개의 영혼 중 하나만 고르세요."}, [28]={hint="획득처: 불타는칼날단 소환사"}, [29]={hint="지옥의 루비를 가지고 가서 잊혀진 땅에 서식하는 지옥사냥개 중 한 마리에게 사용해야 합니다. 성공하면 지옥의 루비와 사로