 tgt="수사 안톤"}, [53]={npc="대령 펜리가스트", tgt="대령 펜리가스트", tag="선택사항", desc="어느 부족의 켄타우로스든 드랍하지만, 이 지점에서는 켄타우로스를 지나는 길에 잡을 일이 없고 콜카르 마을의 몬스터도 레벨이 낮은 편입니다. 경험치를 더 채우고 싶을 때 진행하세요."}, [54]={hint="잊혀진 땅 전역의 켄타우로스를 처치해 조각한 켄타우로스 토템을 5개 입수한 후, 입수한 토템을 나이젤의 야영지에 있는 대령 펜리가스트에게 제출해야 합니다.", tag="선택사항"}, [55]={npc="호르니즈 브림버즐", tgt="호르니즈 브림버즐"}, [56]={hint="언데드 약탈자 30마리를 처치한 후 나이젤의 야영지에 있는 수사 안톤에게 돌아가야 합니다."}, [57]={hint="잊혀진 땅의 호르니즈 브림버즐에게 유령의 플라스마 8개와 유령 유인기 상자를 가져가야 합니다."}, [58]={npc="호르니즈 브림버즐", tgt="호르니즈 브림버즐"}, [59]={npc="수사 안톤", tgt="수사 안톤"}, [60]={npc="대령 펜리가스트", tgt="대령 펜리가스트", tag="선택사항"}, [61]={hint="뒤틀린 불의 토템 5개, 뒤틀린 대지 토템 5개, 뒤틀린 바람 토템 5개, 뒤틀린 물 토템 5개를 모아 아라시 고원에 있는 베이릭 썬더헤임에게 전달해야 합니다.", tag="선택사항", desc="바람 토템은 이곳의 마라우돈일족 켄타우로스에게서 나옵니다. 물 토템은 먼지진흙 습지대 북쪽의 진흙아가미멀록, 불의 토템은 황야의 땅의 바위동굴일족 트로그, 대지 토템은 슬픔의 늪의 드레노어 난민에게서 나오니 지나갈 때 함께 모으세요."}}},
    ["03-39"] = {grind={[1]={mob="나가 탐험가", note="무법항 북쪽 해안의 일반 몬스터. 한곳에 모여 있습니다."}, [2]={mob="붉은해적단 갑판원", note="남쪽 해변의 붉은해적단 주둔지. 붉은해적단 퀘스트와 같은 몬스터입니다."}}, steps={[1]={bindA="{a:35}", desc="귀환석이 아직 대기 중이면 나이젤의 야영지에서 톱니항으로 날아간(테라모어 경유) 뒤 배를 타고 무법항으로 가세요."}, [2]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [3]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [4]={npc="디그", tgt="디그"}, [5]={npc="케복", tgt="케복"}, [6]={npc="함장 시혼", tgt="함장 시혼"}, [7]={npc="선원 블로즈", tgt="선원 블로즈"}, [8]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [9]={npc="애꾸눈 디지", tgt="애꾸눈 디지"}, [10]={npc="행상 러즈고트", tgt="행상 러즈고트"}, [11]={hint="무법항에 있는 함장 시혼이 붉은해적단 칼잡이 10명을 처치하고 붉은해적단 해도와 붉은해적단의 명령서를 가지고 와 달라고 부탁했습니다.", desc="해변을 따라 병을 찾아보세요. 주우면 퀘스트를 시작할 수 있습니다."}, [12]={hint="무법항에 있는 디그가 코담배 15개를 가져다 달라고 부탁했습니다."}, [13]={hint="무법항에 있는 애꾸눈 디지가 붉은해적단에게서 그의 눈을 찾아달라고 부탁했습니다."}, [14]={hint="무법항에 있는 선원 블로즈에게 아키리스 갈대 묶음 10개를 가져가야 합니다."}, [15]={hint="무법항에 있는 남작 레빌가즈를 위해 물의정령 족쇄 6개를 가져와야 합니다.", tag="선택사항"}, [16]={npc="선원 블로즈", tgt="선원 블로즈"}, [17]={npc="선원 블로즈", tgt="선원 블로즈"}, [18]={npc="위스키 슬림", tgt="위스키 슬림"}, [19]={npc="디그", tgt="디그"}, [20]={npc="함장 시혼", tgt="함장 시혼"}, [21]={npc="함장 시혼", tgt="함장 시혼", tag="선택사항"}, [22]={npc="애꾸눈 디지", tgt="애꾸눈 디지", desc="부족한 \"가시덤불 골짜기의 푸른 언덕\" 페이지는 경매장에서 사세요: 1, 4, 6, 8, 10, 11, 14, 16, 18, 20, 21, 24, 25, 26, 27."}, [23]={desc="아직 43레벨이 안 됐다면 무법항 북쪽 해안에서 나가 탐험가를 잡거나, 남쪽 해변에서 붉은해적단을 잡아 43레벨까지 올리세요."}, [24]={hint="무법항에 있는 함장 시혼이 선장 스틸워터, 선장 킬하울과 함장 피랠론을 암살해 달라고 부탁했습니다.", tag="파티가 있을 때, 선택사항", desc="세 척의 배 아래층에 코르텔로의 수수께끼가 나타날 수 있습니다. 얻으면 오른쪽 클릭해 수락하세요."}, [25]={hint="무법항에 있는 크랭크 피즐버브에게 잔질의 혼합물 12개를 가져가야 합니다."}, [26]={hint="무법항에 있는 \"바다늑대\" 맥킨리에게 마우리의 의족, 존존의 황금 망원경과 처키의 큰 반지를 가져가야 합니다."}, [27]={hint="무법항에 있는 드리즐릭에게 무쇠턱 악어 가죽 5개를 가져가야 합니다."}, [28]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리"}, [29]={npc="헤멧 네싱워리", tgt="헤멧 네싱워리", tag="파티가 있을 때, 선택사항"}, [30]={hint="헤멧 네싱워리가 가시덤불 골짜기에 있는 잡기 힘들고 위험한 랩터인 테디스를 처치해 달라고 부탁했습니다.", tag="나중에 지나갈 때 진행, 파티가 있을 때, 선택사항"}, [31]={hint="무법항에 있는 크랭크 피즐버브에게 노래하는 파란 수정 10개를 가져가야 합니다."}, [32]={hint="백골가루부족 