    ["03-40"] = {grind={[1]={mob="사막유랑단 도적", note="가젯잔 남동쪽의 사막유랑단 야영지. 사막유랑단 처단과 같은 몬스터입니다."}, [2]={mob="사막유랑단 어둠마법사", note="같은 야영지의 시전 몬스터. 한 마리씩 유인하세요."}}, steps={[1]={to="Gadgetzan", toA="{a:976}"}, [2]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [3]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [4]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [5]={npc="포직", tgt="포직"}, [6]={npc="자멕", tgt="자멕"}, [7]={npc="자멕", tgt="자멕"}, [8]={npc="아무도 지키지 않는 리즐의 설계도", npcObj=true, desc="리즐 브라스볼츠가 건물을 나간 뒤에 움직이세요."}, [9]={npc="아무도 지키지 않는 리즐의 설계도", npcObj=true}, [10]={npc="포직", tgt="포직"}, [11]={npc="현상수배: 칼리프 스콜피드스팅", npcObj=true}, [12]={npc="현상수배: 칼리프 스콜피드스팅", npcObj=true}, [13]={npc="양수기기사 루글룬켓", tgt="양수기기사 루글룬켓"}, [14]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [15]={npc="조르디 랩포지", tgt="조르디 랩포지"}, [16]={hint="타나리스 사막에서 가젯잔과 다른 폐기물로부터 충분히 떨어진 지점에 방사성 폐기물 상자를 버린 후, 조르디 랩포지에게 가야 합니다.", desc="사막유랑단 야영지로 가는 길에 빈터를 찾아 퀘스트 아이템을 사용하세요."}, [17]={hint="가젯잔의 동쪽에서 10명의 사막유랑단 약탈자와 좀도둑을 처치한 후, 선임기술자 빌지위즐에게 돌아와 보고하십시오."}, [18]={desc="아직 44레벨이 안 됐다면 사막유랑단 야영지에 남아 사막유랑단 도적과 사막유랑단 어둠마법사를 잡아 44레벨까지 올리세요."}, [19]={npc="거만한 의류상", tgt="거만한 의류상"}, [20]={npc="예킨야", tgt="예킨야"}, [21]={npc="스톨리", tgt="스톨리"}, [22]={npc="스톨리", tgt="스톨리"}, [23]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", desc="타나리스를 두 번째로 찾아 모래망치 오우거를 잡을 때 하도록 남겨 두세요."}, [24]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [25]={npc="부두장 스팀피즐", tgt="부두장 스팀피즐", desc="화약심지 항구에서 받은 뒤에만 나타납니다."}, [26]={hint="앙드레를 처치하고 그 증거로 그의 머리카락을 스팀휘들 항구에 있는 보안과장 빌지위즐에게 가져가야 합니다."}, [27]={hint="타나리스의 스팀휘들 항구에 있는 거만한 의류상의 부탁으로 남쪽바다 해적 모자 20개를 모아서 가져가야 합니다."}, [28]={hint="타나리스의 스팀휘들 항구에 있는 보안과장 빌지위즐이 남쪽바다해적단 무법자, 약탈자, 부두일꾼, 칼잡이를 각각 10명씩 처치해 달라고 부탁했습니다."}, [29]={hint="스팀휘들 항구에 있는 스톨리에게 뱃짐을 찾아다 주어야 합니다."}, [30]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [31]={npc="조르디 랩포지", tgt="조르디 랩포지"}, [32]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [33]={npc="양수기기사 루글룬켓", tgt="양수기기사 루글룬켓"}, [34]={hint="가젯잔에 있는 선임기술자 빌지위즐을 위해 사막유랑단 도적 8명, 사막유랑단 암살자 6명, 그리고 사막유랑단 어둠마법사 10명을 처치해야 합니다."}, [35]={hint="칼리프 스콜피드스팅을 처치하고 그 증거로 그의 머리카락을 칼리프 스콜피드스팅의