    ["04-44"] = {grind={[1]={mob="포악한 올빼미야수", note="동부 내륙지 중부의 숲. 수가 많고 올빼미야수 깃털과 같은 몬스터입니다."}, [2]={mob="긴발톱 은빛갈기늑대", note="더 동쪽의 늑대 무리. 흩어져 있어 한 마리씩 잡을 수 있습니다."}}, steps={[1]={to="Southshore", toA="{a:271}", desc="사우스쇼어를 열지 않았다면 메네실 항구로 날아가 북쪽 선착장에서 아우버다인행 배를 타고 사우스쇼어에서 내리세요."}, [2]={text="길을 따라 이 지점까지 달려가세요."}, [3]={npc="폴스타트 와일드해머", tgt="폴스타트 와일드해머"}, [4]={nodeA="{a:348}", node="Aerie Peak"}, [5]={npc="폴스타트 와일드해머", tgt="폴스타트 와일드해머"}, [6]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [7]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [8]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [9]={npc="프라가르 썬더맨틀", tgt="프라가르 썬더맨틀"}, [10]={npc="프라가르 썬더맨틀", tgt="프라가르 썬더맨틀"}, [11]={text="맹금의 봉우리 여관에서 귀환 장소를 설정하세요 (13.80, 41.60).", bindA="{a:348}"}, [12]={npc="랩소디 신디거", tgt="랩소디 신디거", desc="올빼미야수를 잡으러 가는 길에 있습니다. 후속 퀘스트는 술을 가져가야 하니 받지 마세요."}, [13]={hint="에렐라스 앰버스카이를 위해 동부 내륙지에서 올빼미야수 깃털 15개를 모아야 합니다."}, [14]={hint="마른나무껍질 마을 두 곳에 있는 우리들을 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오."}, [15]={desc="아직 47레벨이 안 됐다면 동쪽으로 가서 포악한 올빼미야수와 긴발톱 은빛갈기늑대를 잡아 47레벨까지 올리고, 올빼미야수 깃털도 함께 모으세요."}, [16]={hint="맹금의 봉우리에 있는 프라가르 썬더맨틀에게 트롤 전통 목걸이 5개를 가져다주어야 합니다."}, [17]={hint="가젯잔에 있는 스프링클이 제비수염버섯을 하나 구해 가지고 올 것을 부탁했습니다."}, [18]={hint="녹색 녹괴물 10마리와 비취 수액괴물 10마리를 처치한 후 맹금의 봉우리에 있는 프라가르 썬더맨틀에게 돌아와 보고하십시오."}, [19]={npc="프라가르 썬더맨틀", tgt="프라가르 썬더맨틀"}, [20]={npc="프라가르 썬더맨틀", tgt="프라가르 썬더맨틀"}, [21]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [22]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [23]={hint="줄의 제단 위를 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오."}, [24]={npc="OOX-09/HL 조난 탐지기", npcObj=true, desc="가방의 OOX-09/HL 조난 탐지기 아이템을 오른쪽 클릭해 퀘스트를 받으세요."}, [25]={npc="유도 로봇 OOX-09/HL", tgt="유도 로봇 OOX-09/HL"}, [26]={npc="유도 로봇 OOX-09/HL", tgt="유도 로봇 OOX-09/HL"}, [27]={hint="전망대 절벽 너머 해안까지 OOX-09/HL을 호위해 간 후 무법항에 있는 오글소프 오브노티쿠스에게 보고해야 합니다."}, [28]={hint="슈퍼 찰칵이 FX로 감메리타의 즉석사진을 찍은 후, 루테란 마을에 있는 다린 라이트윈드에게 돌아가야 합니다."}, [29]={hint="무법항에 있는 위스키 슬림이 잃어버린 퍼플리버보스 포트 와인을 찾아 달라고 부탁했습니다."}, [30]={bindA="{a:348}"}, [31]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [32]={npc="그리핀 조련사 탈론액스", tgt="그리핀 조련사 탈론액스"}, [33]={to="Thelsamar", toA="{a:144}"}, [34]={text="텔사마 여관에서 귀환석 위치를 설정하세요(35.40, 48.40).", bindA="{a:144}"}, [35]={text="길을 따라 이 지점까지 달려가세요."}, [36]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="파티가 있을 때, 선택사항", desc="정기의 도움(가시덩굴 우리)과 폭풍과 대지와 불을 먼저 끝내야 받을 수 있습니다."}, [37]={hint="획득처: 맹렬한 폭풍우", tag="파티가 있을 때, 선택사항", desc="임시 주둔지에서 메네실 항구로 비행하고, 남쪽 부두에서 배를 타고 테라모어로 가서 탈라나르로 비행한 뒤, 동쪽으로 걸어 버섯구름 봉우리에 들어가세요."}, [38]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="파티가 있을 때, 선택사항", desc="탈라나르에서 테라모어로 비행하고, 배를 타고 메네실 항구로 간 뒤 임시 주둔지로 비행하세요."}, [39]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="선택사항"}, [40]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항"}, [41]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라"}, [42]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", desc="필요: 붉은머리부족의 어금니 ×30, 생명의 뿌리 ×8, 떠도는 정령의 정수 ×1. 떠도는 정령의 정수: 불타는 부적, 천둥 부적, 용마루장식 부적 각 8개를 옆의 가마솥에 가져가 교환합니다. 생명의 뿌리, 부적 세 종류: 경매장에서 살 수 있습니다."}, [43]={hint="알터랙에 있는 바람의감시자 바스라에게 바스라의 양피지에 적혀 있는 물건들을 가져가야 합니다."}, [44]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라"}, [45]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라"}, [46]={hint="바람의감시자 바스라에게 소용돌이의 눈을 가져가야 합니다."}, [47]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라"}, [48]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", desc="보상: 소용돌이 무기."}, [49]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", desc="보상: 소용돌이 무기."}}},
    ["04-45"] = {grind={[1]={mob="검은무쇠단 감독관", note="용광로 외곽의 검은무쇠 드워프. 레벨이 알맞습니다."}, [2]={mob="검은무쇠단 노예상인", note="용광로 남쪽. 레벨이 조금 낮고 흩어져 있습니다."}}, steps={[1]={npc="시그런 아이언휴", tgt="시그런 아이언휴", tag="선택사항", desc="진행하다 보면 보통 이글거리는 불꽃의 부적을 얻습니다. 떨어지지 않으면 포기하세요."}, [2]={npc="가렉", tgt="가렉", tag="파티가 있을 때, 선택사항", desc="50레벨 정예 검은 비룡 두 마리를 처치해야 합니다. 파티가 없다면 건너뛰세요."}, [3]={hint="대지의 봉인을 사용하여 자수정, 오팔, 다이아몬드의 기둥을 작동시켜 마법석을 모아야 합니다.", tag="나중에 지나갈 때 진행, 파티가 있을 때, 선택사항"}, [4]={npc="대지의 봉인", npcObj=true, tag="파티가 있을 때, 선택사항"}, [5]={npc="대지의 봉인", npcObj=true, tag="파티가 있을 때, 선택사항"}, [6]={npc="가렉", tgt="가렉", tag="파티가 있을 때, 선택사항"}, [7]={npc="시그런 아이언휴", tgt="시그런 아이언휴", tag="선택사항"}, [8]={hint="고통의 요새에 있는 사자 인페르누스를 처치하고 아이언포지에 있는 조언자 벨그룸에게 그의 죽음에 대한 증거를 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [9]={text="황야의 땅에서 서쪽으로 가서 호드 야영지 카르가스 옆 산길로 이글거리는 협곡에 들어가세요. 카르가스는 피해서 가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [10]={npc="나무 간이화장실", npcObj=true, desc="비단 옷감은 경매장에서 살 수 있습니다. 15개가 필요합니다."}, [11]={hint="검은무쇠 지질학자 8명을 처치하고 이글거리는 협곡의 화장실에 갇힌 사람에게 비단 옷감 15개를 가져가야 합니다."}, [12]={text="난폭한 마르골을 처치하세요. 경험치가 많습니다.", tag="선택사항", desc="마르골의 뿔은 이글거리는 협곡 열쇠 퀘스트 라인을 시작합니다. 싸우기 싫으면 건너뛰세요. 이후 관련 단계는 자동으로 생략되며, 마지막에 아이언포지에서 토륨 조합 거점으로 비행해 돌아갑니다."}, [13]={npc="마르골의 뿔", npcObj=true, tag="선택사항, 파티가 있을 때", desc="가방의 마르골의 뿔 아이템을 오른쪽 클릭해 퀘스트를 받으세요."}, [14]={npc="나무 간이화장실", npcObj=true}, [15]={npc="나무 간이화장실", npcObj=true, tag="선택사항", desc="제출에는 네 가지가 필요합니다: 변소 옆 장부, 유리그물거미 다리 ×20, 먼지진흙 습지대의 기한 지난 소포, 슬픔의 늪 자르퀴아의 검. 빠진 것은 일부러 가지 않아도 됩니다."}, [16]={hint="굿스틸 장부를 가지고 거기에 적힌 물건들을 다 모은 다음 타나리스에 있는 크린클 굿스틸을 찾아가야 합니다.", tag="재료가 모이면 진행"}, [17]={npc="도리우스 스톤텐더", tgt="도리우스 스톤텐더", desc="도리우스를 북쪽으로 호위하세요; 매복 후 그 자리에서 그을린 편지를 주워 제출하세요."}, [18]={npc="그을린 편지", npcObj=true}, [19]={npc="그을린 편지", npcObj=true}, [20]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [21]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [22]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [23]={nodeA="{a:1446}", node="Thorium Point"}, [24]={npc="구인광고/분실물센터/지명수배", npcObj=true, tag="파티가 있을 때, 선택사항", desc="감독관 말토리우스(Maltorius)는 50레벨 정예입니다. 파티가 없다면 건너뛰세요."}, [25]={npc="구인광고/분실물센터/지명수배", npcObj=true}, [26]={npc="구인광고/분실물센터/지명수배", npcObj=true}, [27]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [28]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드", tag="선택사항"}, [29]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [30]={npc="수석대장장이 버니네이트", tgt="수석대장장이 버니네이트"}, [31]={bindA="{a:144}"}, [32]={npc="산악경비대 페블비티", tgt="산악경비대 페블비티", tag="선택사항"}, [33]={npc="산악경비대 페블비티", tgt="산악경비대 페블비티"}, [34]={to="아이언포지"}, [35]={npc="베이릭 썬더헤임", tgt="베이릭 썬더헤임", tag="선택사항"}, [37]={npc="도서관장 소리우스", tgt="도서관장 소리우스"}, [38]={npc="도서관장 소리우스", tgt="도서관장 소리우스"}, [39]={npc="도서관장 소리우스", tgt="도서관장 소리우스", tag="선택사항"}, [40]={npc="도서관장 소리우스", tgt="도서관장 소리우스"}, [41]={npc="조언자 벨그룸", tgt="조언자 벨그룸", tag="파티가 있을 때, 선택사항"}, [42]={to="Thelsamar", toA="{a:144}", tag="선택사항", desc="이글거리는 협곡의 열쇠 가 있을 때만 페블비티에게 돌아가 열쇠를 받으세요. 없으면 건너뛰고 아이언포지에서 토륨 조합 거점으로 바로 비행해 돌아가세요."}, [43]={npc="산악경비대 페블비티", tgt="산악경비대 페블비티", tag="선택사항"}, [44]={text="방금 얻은 이글거리는 협곡 열쇠로 산악병 페블비티 옆 문을 열고 터널을 지나 이글거리는 협곡으로 들어가세요.", tag="선택사항"}, [45]={to="Thorium Point", toA="{a:1446}", desc="이글거리는 협곡 열쇠가 없다면 아이언포지에서 이글거리는 협곡으로 바로 비행하세요. 이미 터널로 들어왔다면 건너뛰세요."}, [46]={hint="화염의 심장 4개와 골렘 기름 4개를 모아 벨라로크 윈드블레이드에게 가져가야 합니다."}, [47]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [48]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [49]={hint="이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다."}, [50]={hint="검은무쇠 감독관 15명과 검은무쇠 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다."}, [51]={hint="이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다."}, [52]={hint="이글거리는 협곡의 고원과 용암 웅덩이에 서식하는 불타는 용암거미 20마리를 찾아 처치해야 합니다.", tag="선택사항", desc="따로 돌아가야 하며 근처에 다른 목표가 없습니다. 바쁘면 건너뛰어도 됩니다."}, [53]={hint="용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다."}, [54]={desc="아직 48레벨이 안 됐다면 용광로 외곽에서 검은무쇠단 감독관과 검은무쇠단 노예상인을 잡아 48레벨까지 올리세요."}, [55]={hint="이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 