파티가 있을 때만 여기서 52까지 올리세요. 혼자라면 건너뛰세요."}, [90]={to="아이언포지", desc="귀환석을 쓸 수 있으면 텔사마로 귀환한 뒤 거기서 날아가고, 아니면 토륨 조합 거점(37.90, 30.40)으로 돌아가 비행 조련사를 찾으세요."}, [91]={npc="도서관장 소리우스", tgt="도서관장 소리우스", tag="파티가 있을 때, 선택사항"}, [92]={npc="선임탐험가 마겔라스", tgt="선임탐험가 마겔라스", desc="울다만의 백금 원반을 끝내야 받을 수 있습니다."}, [93]={npc="역사학자 카르닉", tgt="역사학자 카르닉"}, [94]={npc="역사학자 카르닉", tgt="역사학자 카르닉"}, [95]={text="아이언포지 여관에서 귀환석 위치를 설정하세요(18.60, 51.60).", bind="아이언포지"}, [96]={to="Nethergarde Keep", toA="{a:1438}", desc="네더가드 요새를 열지 않았다면 다크샤이어로 날아가 동쪽 죽음의 고개를 지나 슬픔의 늪으로 들어간 뒤, 남쪽 저주받은 땅의 네더가드 요새까지 가세요."}, [97]={npc="샤디우스 그림섀이드", tgt="샤디우스 그림섀이드"}, [98]={npc="코르텔로의 수수께끼", npcObj=true, desc="가방의 코르텔로의 수수께끼 아이템을 오른쪽 클릭해 퀘스트를 받으세요. 50레벨부터 수락할 수 있습니다."}, [99]={text="넷가드 요새에서 북쪽으로 저주받은 땅을 나와 슬픔의 늪으로 들어간 뒤 길을 따라 서쪽 늪지 서부로 가세요."}, [100]={npc="젖은 두루마리", npcObj=true}, [101]={npc="젖은 두루마리", npcObj=true}}},
    ["05-d11"] = {name="검은바위 나락", entrance="이글거리는 협곡 34.80, 85.30", steps={[1]={to="Thorium Point", toA="{a:1446}", desc="슬픔의 늪에는 얼라이언스 비행 지점이 없습니다: 서쪽 죽음의 고개를 지나 다크샤이어로 돌아가서 날아가세요.; 죽어서 영혼 상태가 되어야 그가 보입니다: 검은바위 산 안에서 용암에 뛰어들고, 영혼 상태로 퀘스트를 받은 뒤 시체로 달려가 부활하세요."}, [2]={text="토륨 조합 거점에서 남쪽으로 이글거리는 협곡을 가로질러 남쪽 검은바위 산으로 들어가세요."}, [3]={npc="프랑클론 포지라이트", tgt="프랑클론 포지라이트"}, [4]={npc="프랑클론 포지라이트", tgt="프랑클론 포지라이트"}, [5]={npc="프랑클론 포지라이트", tgt="프랑클론 포지라이트"}, [6]={text="검은바위 나락 입구"}, [7]={hint="획득처: 파이너스 다크바이어"}, [8]={npc="프랑클론 포지라이트의 기념비", npcObj=true}, [9]={to="아이언포지", desc="검은바위 산을 나와 북쪽 이글거리는 협곡을 지나 토륨 조합 거점으로 돌아가 그곳에서 날아가세요."}}},
    ["04-46"] = {grind={[1]={mob="하늘갈기고릴라", note="밀림의왕 무클라가 있는 작은 섬의 일반 몬스터. 왕을 잡은 뒤 가는 길에 정리하세요."}, [2]={mob="긴발톱 흑표범", note="같은 섬의 서쪽."}}, steps={[1]={to="Booty Bay", toA="{a:35}", desc="슬픔의 늪에는 얼라이언스 비행 지점이 없습니다. 서쪽 죽음의 고개를 지나 다크샤이어로 돌아가서 날아가세요."}, [2]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [3]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [4]={npc="위스키 슬림", tgt="위스키 슬림"}, [5]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [6]={npc="핀 피즈라켓", tgt="핀 피즈라켓", tag="선택사항"}, [7]={npc="오글소프 오브노티쿠스", tgt="오글소프 오브노티쿠스"}, [8]={npc="오글소프 오브노티쿠스", tgt="오글소프 오브노티쿠스"}, [9]={npc="오글소프 오브노티쿠스", tgt="오글소프 오브노티쿠스"}, [10]={npc="오글소프 오브노티쿠스", tgt="오글소프 오브노티쿠스"}, [11]={npc="오글소프 오브노티쿠스", tgt="오글소프 오브노티쿠스"}, [12]={npc="조심스럽게 접힌 쪽지", npcObj=true, desc="가방의 조심스럽게 접힌 쪽지 아이템을 오른쪽 클릭해 퀘스트를 받으세요. 전에 얻은 접힌 쪽지를 이제 오른쪽 클릭해 퀘스트를 시작하세요."}, [13]={npc="공주 푸바", tgt="공주 푸바"}, [14]={npc="공주 푸바", tgt="공주 푸바", tag="파티가 있을 때, 선택사항"}, [15]={hint="밀림의왕 무클라를 처치하고 공주 푸바에게 열쇠를 가져가 그녀를 구해야 합니다.", tag="파티가 있을 때, 선택사항"}, [16]={npc="공주 푸바", tgt="공주 푸바", tag="파티가 있을 때, 선택사항"}, [17]={desc="아직 49레벨이 안 됐다면 섬에 남아 하늘갈기고릴라와 긴발톱 흑표범을 잡아 49레벨까지 올리세요."}, [18]={hint="의술사 운바그와를 찾아 흉포한 모크를 불러내도록 해야 합니다. 핀 피즈라켓에게 모크의 심장을 가져가야 합니다.", tag="나중에 지나갈 때 진행"}, [19]={npc="핀 피즈라켓", tgt="핀 피즈라켓", tag="선택사항"}, [20]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [21]={hint="톱니항에 있는 마본 리벳시커의 작업장에서 마본의 궤짝에 담긴 아탈라이 돌무리를 회수해야 합니다."}, [22]={to="Theramore"}, [23]={npc="곰팡이 슨 두루마리", npcObj=true}, [24]={npc="곰팡이 슨 두루마리", npcObj=true, tag="선택사항"}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", toA="{a:976}", desc="두루마리는 먼지진흙 습지대 남서쪽 랩터 동굴에 있습니다. 먼저 동쪽으로 걸어 테라모어(67.48, 51.30)로 돌아간 뒤 비행하세요."}, [2]={npc="크린클 굿스틸", tgt="크린클 굿스틸", tag="재료가 모이면 진행"}, [3]={npc="스프링클", tgt="스프링클"}, [4]={npc="스프링클", tgt="스프링클"}, [5]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [6]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [7]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [8]={text="가젯잔에서 큰길을 따라 북쪽 버섯구름 봉우리 소금 평원으로 가세요."}, [9]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [10]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [11]={npc="노움 정비주임", tgt="노움 정비주임"}, [12]={npc="마본 리벳시커", tgt="마본 리벳시커"}, [13]={npc="울둠 대좌", npcObj=true}, [14]={npc="노르간논의 바위감시자", tgt="노르간논의 바위감시자"}, [15]={npc="울둠 대좌", npcObj=true}, [16]={npc="울둠 대좌", npcObj=true}, [17]={text="길을 따라 이 지점까지 달려가세요."}}},
    ["04-48"] = {grind={[1]={mob="채찍줄기 붉은꽃잎덩굴손", note="동쪽의 식물 몬스터 무리. 분화구에 막 들어왔을 때 잡으세요."}, [2]={mob="운고로 고릴라", note="북동쪽 고릴라 동굴 밖. 고릴라 모피와 같은 몬스터입니다."}, [3]={mob="테러닥스", note="마샬의 야영지 동쪽의 절벽."}, [4]={mob="송진껍질괴물", note="야영지 남쪽의 타르 구덩이. 레벨이 높은 편이니 한 마리씩 유인하세요."}}, steps={[1]={text="타나리스 서쪽 산길에서 비탈길을 따라 운고로 분화구로 내려가세요. 토르와 패스파인더는 비탈길 아래 입구 옆에 있습니다.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [2]={npc="토르와 패스파인더", tgt="토르와 패스파인더", tag="높은 레벨 몹을 잡을 수 있을 때 진행, 선택사항"}, [3]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [4]={npc="난파된 나룻배", npcObj=true, desc="빨강, 파랑, 초록, 노랑 수정을 각각 7개 모으고, 랩터에게서 구겨진 일지를 얻으세요."}, [5]={npc="작은 배낭", npcObj=true}, [6]={npc="작은 배낭", npcObj=true}, [7]={hint="사용/수집: 방금 죽은 트레샤돈 시체"}, [8]={desc="67.7, 30.7 근처에서 식물형 몬스터를 잡아 49레벨 절반까지 올리세요."}, [9]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [10]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [11]={hint="운고로 분화구 입구에 있는 토르와 패스파인더에게 라바사우루스 페로몬샘 2개를 가져가야 합니다."}, [12]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [13]={npc="토르와 패스파인더", tgt="토르와 패스파인더", tag="선택사항"}, [14]={hint="토르와의 주머니에 든 물건들로 라르코르위를 불러내 물리친 후 라르코르위의 머리를 운고로 분화구 입구에 있는 토르와 패스파인더에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항", desc="이 퀘스트는 어려운 편입니다. 운고로에 다시 올 때 해도 됩니다."}, [15]={npc="카르나 렘트레블", tgt="카르나 렘트레블"}, [16]={npc="링쿠", tgt="링쿠"}, [17]={npc="링쿠", tgt="링쿠"}, [18]={nodeA="{a:541}", node="Marshal's Refuge"}, [19]={npc="윌리덴 마샬", tgt="윌리덴 마샬"}, [20]={npc="홀라니에 마샬", tgt="홀라니에 마샬"}, [21]={npc="스파크 닐마이너", tgt="스파크 닐마이너"}, [22]={npc="J.D. 콜리", tgt="J.D. 콜리", desc="네 가지 색의 마력의 수정이 운고로 곳곳의 바닥에 흩어져 있습니다. 지나가다 보이는 대로 주워 색깔별로 7개씩 모으세요. 운고로에 두 번째로 올 때 완료하세요."}, [23]={npc="테러닥스 주의", npcObj=true}, [24]={npc="무이긴", tgt="무이긴"}, [25]={npc="쉬즐", tgt="쉬즐"}, [26]={hint="획득처: 운고로 고릴라, 운고로 우레고릴라, 운고로 천둥고릴라", tag="높은 레벨 몹을 잡을 수 있을 때 진행, 선택사항"}, [27]={desc="아직 50레벨이 안 됐다면 고릴라 동굴 밖에 남아 운고로 고릴라를 잡아 50레벨까지 올리세요."}, [28]={hint="운고로 분화구에 있는 윌리덴 마샬에게 식량 상자와 탐사 장비를 가져가야 합니다.", desc="식량 상자는 동쪽 (고릴라 동굴, 토르와로 가는 길)에, 탐사 장비는 남서쪽 (벌레 둥지에서 익룡으로 가는 길)에 있으니, 지나가며 하나씩 주우세요."}, [29]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [30]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [31]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [32]={text="길을 따라 이 지점까지 달려가세요."}, [33]={text="길을 따라 이 지점까지 달려가세요."}, [34]={hint="운고로 분화구에 있는 고리쉬 부화장에서 채집 약병을 사용해 고리쉬집 벽면 견본을 채취하십시오. 유충알이 매달려 있는 방을 찾아야 합니다."}, [35]={text="받아 둔 처치 퀘스트와 수집 퀘스트를 끝내세요."}, [36]={hint="마샬의 야영지에 있는 쉬즐에게 갈퀴 달린 디메트로돈 비늘 8개와 갈퀴 달린 테러닥스 비늘 8개를 가져가야 합니다."}, [37]={hint="붉은꽃잎 15개를 모아 무이긴에게 돌아가야 합니다."}, [38]={hint="테러닥스 10마리와 광포한 테러닥스 15마리를 처치한 후 마샬의 야영지에 있는 스프래글 프록과 대화해야 합니다."}, [39]={npc="쉬즐", tgt="쉬즐"}, [40]={npc="무이긴", tgt="무이긴"}, [41]={npc="무이긴", tgt="무이긴"}, [42]={npc="스프래글 프록", tgt="스프래글 프록"}, [43]={npc="스파크 닐마이너", tgt="스파크 닐마이너"}, [44]={npc="홀라니에 마샬", tgt="홀라니에 마샬"}, [45]={npc="윌리덴 마샬", tgt="윌리덴 마샬"}, [46]={npc="구겨진 일지", npcObj=true, tag="선택사항", desc="몬스터에게서 구겨진 일지를 얻었을 때만 오른쪽 클릭해 퀘스트를 받으세요."}, [47]={npc="윌리덴 마샬", tgt="윌리덴 마샬", tag="선택사항"}, [48]={desc="아직 51레벨이 안 됐다면 야영지 동쪽에서 테러닥스를 잡거나, 남쪽 타르 구덩이에서 송진껍질괴물을 잡아 51레벨까지 올리세요."}, [49]={bind="아이언포지", desc="아이언포지에서 세나리온 의회 퀘스트를 받을 사제는 귀환석 재사용 대기시간이 끝날 때까지 기다리세요. 그 외에는 귀환석 대기 중 마샬의 야영지에서 아우버다인으로 비행한 다음 루테란 마을로 가세요."}, [50]={text="스톰윈드의 안내 퀘스트를 받을 때만 가세요. 아이언포지에서 깊은굴 지하철을 타고 스톰윈드로 가세요.", tag="선택사항"}, [51]={npc="마지노르 뒤마", tgt="마지노르 뒤마", tag="선택사항", desc="스톰윈드의 안내 퀘스트는 건너뛰어도 됩니다. 아즈샤라에 도착해도 먼저 사나스 림요를 찾아 절벽 위로 이동해야 합니다."}, [52]={text="스톰윈드에서 메네실 항구로 비행해 경로에 다시 합류하세요.", tag="선택사항"}, [53]={npc="대사제 로한", tgt="대사제 로한", tag="경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 불사의 영액 1개. 나중에 아즈샤라 불사의 영액에 씁니다.", desc="아즈샤라의 오그틴크에게 제출하세요."}, [54]={to="Menethil Harbor", toA="{a:150}"}, [55]={to="아우버다인", from="Menethil Harbor", fromA="{a:150}", desc="이 배는 도중에 사우스쇼어에 정박합니다. 아우버다인에서 내리세요."}, [56]={to="Rut'theran Village", toA="{a:702}"}, [57]={npc="에렐라스 앰버스카이", tgt="에렐라스 앰버스카이"}, [58]={npc="다린 라이트윈드", tgt="다린 라이트윈드"}, [59]={npc="다린 라이트윈드", tgt="다린 라이트윈드"}, [60]={text="루테란 마을의 차원문으로 들어가 다르나서스로 가세요.", tag="경매장에서 미리 사 두세요(부캐가 우편으로 보내도 됩니다): 미스릴 형틀 1개. 나중에 운고로 분화구 에이미 01 추적에 씁니다."}, [61]={npc="그라시나 스피릿마이트", tgt="그라시나 스피릿마이트"}, [62]={npc="그라시나 스피릿마이트", tgt="그라시나 스피릿마이트"}, [63]={npc="아스타리 스타시커", tgt="아스타리 스타시커", tag="파티가 있을 때, 선택사항"}, [64]={npc="도리온", tgt="도리온", desc="다르나서스(또는 아이언포지, 스톰윈드)에서 받아 아즈샤라의 오그틴크에게 완료하세요."}, [65]={text="다르나서스의 차원문으로 들어가 루테란 마을로 돌아가세요."}, [66]={to="Astranaar", toA="{a:415}"}, [67]={text="아스트라나르 여관에서 귀환석 위치를 설정하세요(37.00, 49.20).", bindA="{a:415}"}, [68]={npc="사나스 림요", tgt="사나스 림요", tag="선택사항", desc="안내 퀘스트를 받았을 때만 여기서 완료하세요."}, [69]={text="사나스 림요와 대화해 절벽 위의 대마법사 실렘에게 갈 수 있게 이동시켜 달라고 하세요."}, [70]={npc="대마법사 실렘", tgt="대마법사 실렘"}, [71]={hint="대마법사 실렘에게 반짝이는 가루 10개를 가져가야 합니다."}, [72]={npc="대마법사 실렘", tgt="대마법사 실렘", desc="먼지는 산 아래에 있습니다. 돌아올 때도 같은 방법으로 사나스 림요에게 이동시켜 달라고 하세요."}, [73]={npc="대마법사 실렘", tgt="대마법사 실렘"}, [74]={hint="대마법사 실렘에게 마력 깃든 산호 6개를 가져가야 합니다."}, [75]={npc="대마법사 실렘", tgt="대마법사 실렘"}, [76]={npc="대마법사 실렘", tgt="대마법사 실렘", tag="파티가 있을 때, 선택사항", desc="몰파즈는 아탈학카르 신전에 있습니다."}, [77]={hint="몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다.", tag="파티가 있을 때, 선택사항", desc="몰파즈는 아탈학카르 신전에 있습니다."}, [78]={npc="대마법사 실렘", tgt="대마법사 실렘", tag="파티가 있을 때, 선택사항", desc="몰파즈는 아탈학카르 신전에 있습니다. 절벽을 내려갈 때는 귀환석을 쓰거나 실렘 옆의 이동 선택지를 찾아보세요."}, [79]={text="탈렌드리스 초소로 돌아가 아스트라나르로 비행한 뒤, 큰길을 따라 북쪽으로 악령의 숲에 들어가세요."}, [80]={npc="오그틴크", tgt="오그틴크"}, [81]={npc="오그틴크", tgt="오그틴크"}, [82]={hint="건강한 순록의 분비샘 4개를 찾아 아즈샤라의 오그틴크에게 가져가야 합니다. 오그틴크는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있습니다."}, [83]={npc="오그틴크", tgt="오그틴크"}, [84]={npc="오그틴크", tgt="오그틴크", desc="불사의 영액 ×1: 경매장에서 살 수 있습니다."}, [85]={hint="아즈샤라의 오그틴크에게 불사의 영액을 가져다주어야 합니다. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 있습니다."}, [86]={npc="오그틴크", tgt="오그틴크"}, [87]={npc="오그틴크", tgt="오그틴크", tag="파티가 있을 때, 선택사항", desc="몰파즈는 아탈학카르 신전에 있습니다."}, [88]={hint="아탈학카르 신전에서 몰파즈를 처치하고 그의 피를 악령의 숲에 있는 그레타 모스후프에게 가져다주어야 합니다. 가라앉은 신전의 입구는 슬픔의 늪에 있습니다.", tag="파티가 있을 때, 선택사항", desc="몰파즈는 아탈학카르 신전에 있습니다."}, [89]={text="아즈샤라에 있다면 탈렌디스 초소로 돌아가 아스트라나르까지 비행한 뒤 북쪽 악령숲으로 가세요. 사원에서 나왔다면 악령숲의 에메랄드 성소로 바로 가세요."}, [90]={npc="오그틴크", tgt="오그틴크", desc="다르나서스(또는 아이언포지, 스톰윈드)에서 받아 아즈샤라의 오그틴크에게 완료하세요."}, [91]={npc="오그틴크", tgt="오그틴크"}, [92]={hint="아즈샤라에 있는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 완전한 순록 뿔 한 쌍을 가져가야 합니다."}, [93]={npc="오그틴크", tgt="오그틴크"}, [94]={npc="오그틴크", tgt="오그틴크"}, [95]={hint="아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 폭풍히드라 비늘 6개를 가져가야 합니다."}, [96]={npc="오그틴크", tgt="오그틴크"}, [97]={npc="오그틴크", tgt="오그틴크", tag="파티가 있을 때, 선택사항", desc="녹색 비룡은 아탈학카르 신전에 있습니다."}, [98]={hint="아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 몰파즈의 이빨을 가져가야 합니다.", tag="파티가 있을 때, 선택사항", desc="녹색 비룡은 아탈학카르 신전에 있습니다."}, [99]={npc="오그틴크", tgt="오그틴크", tag="파티가 있을 때, 선택사항", desc="녹색 비룡은 아탈학카르 신전에 있습니다."}, [100]={text="탈렌드리스 초소로 돌아가 아스트라나르로 비행한 뒤, 큰길을 따라 북쪽으로 악령의 숲에 들어가세요."}}},
    ["04-49"] = {grind={[1]={mob="자에데나르 수호병", note="자에데나르 입구 일대의 일반 몬스터."}, [2]={mob="자에데나르 이교도", note="수호병과 섞여 있는 시전 몬스터."}}, steps={[1]={text="아스트라나르에서 큰길을 따라 북쪽 악령의 숲으로 들어가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [2]={npc="아라탄드리스 실버스카이", tgt="아라탄드리스 실버스카이"}, [3]={npc="그라즐", tgt="그라즐"}, [4]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [5]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="파티가 있을 때, 선택사항, 재료가 모이면 진행"}, [6]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [7]={npc="타론 레드페더", tgt="타론 레드페더", tag="선택사항"}, [8]={hint="그라즐이 자기 일족의 친구임을 입증하려면 마른가지일족 전사, 길잡이, 정원사를 각각 6마리씩 처치해달라고 부탁했습니다. 임무를 마치면 악령의 숲 남쪽, 에메랄드 성소 근처에 있는 그라즐에게 돌아가십시오."}, [9]={npc="그라즐", tgt="그라즐"}, [10]={npc="그라즐", tgt="그라즐"}, [11]={hint="비취불꽃의 악마추종자 11명, 그림자추적자 9명, 도적 9명과 사바스라스를 처치해야 합니다. 임무를 완수하면 에리단 블루윈드에게 돌아가야 합니다."}, [12]={hint="자에데나르에 가서 자에데나르 사냥개 4마리, 자에데나르 수호병 4명, 자에데나르 숙련사제 6명, 자에데나르 이교도 6명을 처치하고 그레타 모스후프에게 돌아가야 합니다."}, [13]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [14]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [15]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [16]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [17]={hint="빈 수통을 자에데나르 중심부의 달샘으로 가져가서 채운 다음 악령의 숲에 있는 그레타 모스후프에게 가져 가야 합니다."}, [18]={desc="자에데나르 35, 59 부근에서 몬스터를 잡으세요."}, [19]={hint="불벼락 골짜기를 탐색하는 동안 혼돈의 불길 2마리와 혼돈의 소산물 2마리를 처치해야 합니다. 분화구를 조사해 아직도 부패한 물이 남아 있는지 확인하고 악령의 숲의 타론 레드페더에게 돌아가야 합니다.", tag="선택사항", desc="따로 돌아가야 하며 근처에 다른 목표가 없습니다. 바쁘면 건너뛰어도 됩니다."}, [20]={hint="에리단 블루윈드를 위해 비취불꽃 지옥소환사 8명과 배반자 8명, 그리고 요술사 8명과 사바릭을 처단해야 합니다. 임무가 완수되는 대로 에리단에게 돌아가십시오."}, [21]={npc="사바릭의 플룻", npcObj=true, desc="가방의 사바릭의 플룻 아이템을 오른쪽 클릭해 퀘스트를 받으세요."}, [22]={hint="사바릭의 플룻과 악의 비취불꽃 매듭 5개를 악령의 숲 남쪽의 에리단 블루윈드에게 가져가야 합니다."}, [23]={hint="악령의 숲에 있는 아라탄드리스 실버스카이에게 핏빛 호박석 15개를 가져가야 합니다."}, [24]={nodeA="{a:1998}", node="Talonbranch Glade"}, [25]={npc="나피엔", tgt="나피엔"}, [26]={npc="나피엔", tgt="나피엔"}, [27]={hint="나피엔이 마른가지일족 보초, 복수자, 주술사를 각각 6마리씩 처치해 달라고 부탁했습니다. 일을 마치면 악령의 숲 북쪽, 나무구렁 요새 입구 근처에 있는 나피엔에게 돌아가십시오."}, [28]={npc="나피엔", tgt="나피엔"}, [29]={text="길을 따라 이 지점까지 달려가세요.", desc="여기서 나무구렁 요새 동굴로 들어가 끝까지 지나가면 여명의 설원입니다."}, [30]={node="달의 숲", desc="나무구렁 요새 동굴에는 달의 숲으로 가는 갈림길이 있습니다. 먼저 가서 비행 지점을 열고, 다시 동굴로 돌아와 여명의 설원 쪽으로 가세요. 나중에 하이잘 산 구간에서는 달의 숲으로 날아가게 됩니다."}, [31]={npc="살파", tgt="살파"}, [32]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [33]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [34]={npc="메지 페핀로커", tgt="메지 페핀로커"}, [35]={npc="제시카 레드패스", tgt="제시카 레드패스"}, [36]={nodeA="{a:2255}", node="Everlook"}, [37]={npc="전지전능한 나이비", tgt="전지전능한 나이비"}, [38]={npc="임프시", tgt="임프시"}, [39]={npc="임프시", tgt="임프시", desc="지옥 옷감 ×1: 경매장에서 살 수 있습니다."}, [40]={hint="악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다."}, [41]={npc="임프시", tgt="임프시"}, [42]={npc="임프시", tgt="임프시"}, [43]={hint="악령의 숲에 있는 임프시에게 썩은 나무 10개와 피멍울 정수 4개를 가져가야 합니다."}, [44]={npc="임프시", tgt="임프시"}, [45]={npc="임프시", tgt="임프시", tag="파티가 있을 때, 선택사항"}, [46]={hint="가라앉은 사원에 있는 트롤의 부두 깃털 6개를 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [47]={npc="임프시", tgt="임프시", tag="파티가 있을 때, 선택사항"}, [48]={npc="임프시", tgt="임프시"}, [49]={hint="악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다."}, [50]={npc="임프시", tgt="임프시"}, [51]={npc="임프시", tgt="임프시", desc="크로쉬우스는 악령의 숲 북쪽에 있습니다. 파티가 필요합니다."}, [52]={hint="악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다.", desc="크로쉬우스는 악령의 숲 북쪽에 있습니다. 파티가 필요합니다."}, [53]={npc="전지전능한 나이비", tgt="전지전능한 나이비", desc="크로쉬우스는 악령의 숲 북쪽에 있습니다. 파티가 필요합니다."}}},
    ["04-50"] = {steps={[1]={to="Feathermoon Stronghold", toA="{a:1116}"}, [2]={npc="프랫 맥그루벤", tgt="프랫 맥그루벤"}, [3]={npc="트로야스 문브리즈", tgt="트로야스 문브리즈"}, [4]={npc="트로야스 문브리즈", tgt="트로야스 문브리즈"}, [5]={npc="그레간 브루스퓨", tgt="그레간 브루스퓨"}, [6]={npc="무쇠이빨", tgt="무쇠이빨"}, [7]={hint="페랄라스 북쪽에서 그레간 브루스퓨를 찾아야 합니다. 그에게서 앞날의 비약을 얻는 방법을 배워 여명의 설원에 있는 도노바 스노우덴에게 돌아가야 합니다.", desc="그레간이 미끼를 줍니다: 그걸로 미블론을 떼어 놓고 에보뿌리를 주운 뒤, 돌아와 앞날의 비약으로 바꾸세요."}, [8]={hint="트로야스의 지팡이에 힘을 불어넣고 에퀴넥스 비석탑을 찾아야 합니다.", desc="더 가면 위로 뛰어올라 지름길로 갈 수 있습니다."}, [9]={npc="샤이 리프러너", tgt="샤이 리프러너"}, [10]={npc="에퀴넥스 비석탑", npcObj=true, desc="가방에 있는 지팡이를 사용하세요."}, [11]={npc="에퀴넥스 비석탑", npcObj=true}, [12]={npc="샤이 리프러너", tgt="샤이 리프러너", tag="호위"}, [13]={hint="궤짝에서 샤이의 종을 집어야 합니다."}, [14]={npc="무쇠이빨", tgt="무쇠이빨"}, [15]={hint="페랄라스의 페더문 요새에 있는 프랫 맥그루벤에게 무쇠설인 가죽 10개를 가져가야 합니다."}, [16]={npc="온전한 설인 가죽", npcObj=true, tag="선택사항", desc="설인을 잡다가 온전한 설인 가죽이 나오면 오른쪽 클릭해 수락하세요."}, [17]={npc="프랫 맥그루벤", tgt="프랫 맥그루벤"}, [18]={npc="프랫 맥그루벤", tgt="프랫 맥그루벤", tag="선택사항"}, [19]={npc="트로야스 문브리즈", tgt="트로야스 문브리즈"}}},
    ["04-51"] = {grind={[1]={mob="눈사태일족 길잡이", note="도노바 북쪽의 눈사태일족 펄볼그 야영지. 펄볼그 퀘스트와 같은 몬스터입니다."}, [2]={mob="눈사태일족 토템술사", note="같은 야영지의 시전 몬스터."}}, steps={[1]={bindA="{a:415}", desc="귀환석이 아직 대기 중이면 페더문 요새에서 아스트라나르로 날아간(아우버다인 경유) 뒤 북쪽 악령의 숲으로 걸어가세요."}, [2]={npc="아라탄드리스 실버스카이", tgt="아라탄드리스 실버스카이"}, [3]={npc="아라탄드리스 실버스카이", tgt="아라탄드리스 실버스카이"}, [4]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [5]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="파티가 있을 때, 선택사항, 재료가 모이면 진행"}, [6]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [7]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [8]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [9]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [10]={npc="타론 레드페더", tgt="타론 레드페더"}, [11]={hint="획득처: 저주받은 수액괴물, 부패한 수액괴물, 썩은 수액괴물", desc="가방에 세나리온 등불이 있어야 드랍됩니다. 무쇠부리 올빼미는 성소 서쪽에, 수액괴물은 북서쪽 웅덩이에 있습니다."}, [12]={npc="아라탄드리스 실버스카이", tgt="아라탄드리스 실버스카이"}, [13]={npc="도노바 스노우덴", tgt="도노바 스노우덴", desc="아스트라나르로 돌아가 갈퀴가지 숲으로 날아간 뒤, 북쪽 나무구렁 요새를 지나 여명의 설원으로 가세요."}, [14]={npc="도노바 스노우덴", tgt="도노바 스노우덴", desc="가젯잔 밖의 무덤에서 앞날의 비약을 마시고, 영혼 상태로 개리얀을 찾으세요."}, [15]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [16]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [17]={desc="눈사태일족 야영지 32, 36 부근에서 펄볼그를 잡으세요."}, [18]={npc="그레고르 그레이스톤", tgt="그레고르 그레이스톤"}, [19]={npc="그레고르 그레이스톤", tgt="그레고르 그레이스톤"}, [20]={to="Ratchet", toA="{a:392}", desc="탈렌드리스 초소를 경유합니다."}, [21]={npc="리브 리즐픽스", tgt="리브 리즐픽스"}, [22]={npc="이슬렌 워터시어", tgt="이슬렌 워터시어"}, [23]={npc="이슬렌 워터시어", tgt="이슬렌 워터시어"}, [24]={to="Gadgetzan", toA="{a:976}"}, [25]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [26]={text="앞날의 비약을 마신 뒤 죽은 상태를 유지하고 유령으로 퀘스트 NPC를 찾으세요."}, [27]={npc="개리얀", tgt="개리얀"}, [28]={npc="개리얀", tgt="개리얀"}, [29]={text="시체로 돌아가 부활하세요."}, [30]={npc="눈에 띄는 묘비", npcObj=true}, [31]={npc="눈에 띄는 묘비", npcObj=true}, [32]={npc="트란렉", tgt="트란렉"}, [33]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그", tag="선택사항"}}},
    ["04-52"] = {name="운고로 분화구", steps={[1]={to="Marshal's Refuge", toA="{a:541}"}, [2]={npc="링쿠", tgt="링쿠"}, [3]={npc="링쿠", tgt="링쿠"}, [4]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [5]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [6]={npc="스프래글 프록", tgt="스프래글 프록"}, [7]={npc="홀라니에 마샬", tgt="홀라니에 마샬", tag="선택사항, If offered", desc="책 배달 퀘스트: NPC가 제공하면 받고, 하이잘 산 영원의 정상으로 가져가 제출하세요. 퀘스트가 보이지 않으면 일단 건너뛰세요."}, [8]={hint="매우 끈적거리는 타르 12개를 모아 가젯잔에 있는 트란렉에게 갖다 주어야 합니다."}, [9]={npc="크래클", tgt="크래클"}, [10]={hint="운고로 분화구의 화산 주위에 있는 불의 정령에게서 운고로 재 견본 9개를 모아 톱니항에 있는 리브 리즐픽스에게 가져가야 합니다."}, [11]={hint="운고로 분화구에 있는 크래클이 불기둥 마루에서 가장 뜨거운 자리를 찾도록 요청했습니다."}, [12]={hint="획득처: 병정 고리쉬, 일꾼 고리쉬, 갈퀴발톱 고리쉬. 사용/수집: 운고로 흙더미", tag="선택사항", desc="따로 돌아가야 하며 근처에 다른 목표가 없습니다. 바쁘면 건너뛰어도 됩니다."}, [13]={npc="크래클", tgt="크래클"}, [14]={npc="크래클", tgt="크래클"}, [15]={npc="링고 스타", tgt="링고 스타", desc="호위 퀘스트입니다. 파티라면 모두 진행 상황이 같아졌을 때 수락하고, 자동 수락/완료를 끄세요."}, [16]={npc="링고 스타", tgt="링고 스타"}, [17]={hint="마샬의 야영지에 있는 스프래글 프록에게 링고 스타를 데려다 주어야 합니다.", tag="호위", desc="링고 스타를 마샬의 야영지로 데려가세요. 그는 도중에 쓰러집니다. 쓰러지면 스프래글의 수통을 사용하세요."}, [18]={npc="스프래글 프록", tgt="스프래글 프록"}, [19]={npc="에이미 01", tgt="에이미 01"}, [20]={npc="에이미 01", tgt="에이미 01"}, [21]={hint="미스릴 형틀을 찾아 운고로 분화구에 있는 에이미 01에게 돌아가야 합니다.", desc="미스릴 외피는 미리 경매장에서 사거나 기계공학 플레이어에게 제작을 부탁하세요."}, [22]={npc="에이미 01", tgt="에이미 01"}, [23]={hint="운고로 분화구 입구에 있는 토르와 패스파인더에게 우차의 모피를 가져가야 합니다."}, [24]={npc="에이미 01", tgt="에이미 01"}, [25]={hint="운고로 분화구에 있는 카르나 렘트래블에게로 에이미 01을 호위해 가야 합니다.", tag="호위", desc="에이미 01을 카르나 렘트레블에게 호위하세요. 길에서 몬스터가 공격하니 보호하세요."}, [26]={npc="카르나 렘트레블", tgt="카르나 렘트레블"}, [27]={hint="붉은 마력의 수정, 푸른 마력의 수정, 노란 마력의 수정, 녹색 마력의 수정을 각각 7개씩 모아 마샬의 야영지에 있는 J.D. 콜리에게 가져가야 합니다.", desc="네 가지 색의 수정이 분화구 곳곳의 바닥에 흩어져 있습니다. 앞서 다 모으지 못한 것을 채우세요."}, [28]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [29]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [30]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [31]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [32]={hint="운고로 분화구에 있는 북쪽 수정탑의 위치를 알아내야 합니다."}, [33]={hint="운고로 분화구에 있는 동쪽 수정탑의 위치를 알아내야 합니다."}, [34]={hint="운고로 분화구에 있는 서쪽 수정탑의 위치를 알아내야 합니다."}, [35]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [36]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [37]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [38]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [39]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [40]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [41]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [42]={hint="붉은갓버섯 8개와 고리쉬 독침 8개를 모아서 운고로 분화구에 있는 토르와 패스파인더에게 돌아가십시오."}, [43]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [44]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [45]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [46]={npc="토르와 패스파인더", tgt="토르와 패스파인더", tag="파티가 있을 때, 선택사항"}, [47]={hint="가라앉은 사원 하층부의 수호병으로부터 썩은 덩굴을 찾은 후 토르와 패스파인더에게 돌아가십시오.", tag="파티가 있을 때, 선택사항"}, [48]={npc="토르와 패스파인더", tgt="토르와 패스파인더", tag="파티가 있을 때, 선택사항"}, [49]={text="토르와 패스파인더 근처에는 비행 지점이 없습니다. 그의 뒤쪽 경사로로 운고로 분화구를 나가 타나리스로 들어가서 북동쪽으로 달려 가젯잔으로 가세요."}, [50]={npc="트란렉", tgt="트란렉"}, [51]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그", tag="선택사항"}, [52]={to="Ratchet", toA="{a:392}", desc="테라모어를 경유합니다."}, [53]={npc="리브 리즐픽스", tgt="리브 리즐픽스"}, [54]={bindA="{a:415}"}, [55]={to="아우버다인"}, [56]={text="아우버다인 여관에서 여관주인 샤우시에게서 귀환석 위치를 설정하세요(37.04, 44.13).", bind="아우버다인"}, [57]={to="Rut'theran Village", toA="{a:702}"}, [58]={npc="에렐라스 앰버스카이", tgt="에렐라스 앰버스카이"}, [59]={text="루테란 마을의 차원문으로 들어가 다르나서스로 가세요."}, [60]={hint="다르나서스에 있는 달의 신전으로 가서 에리단의 유리병을 사용하여 축복받은 물을 담아 와야 합니다. 꽉 찬 물병을 에리단에게 가져와야 합니다."}, [61]={text="다르나서스의 차원문으로 들어가 루테란 마을로 돌아가세요."}, [62]={to="Astranaar", toA="{a:415}"}, [63]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [64]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="선택사항, If offered", desc="편지 배달 퀘스트: NPC가 제공하면 받고, 하이잘 산으로 가져가 은둔자 케타라스에게 제출하세요. 퀘스트가 보이지 않으면 일단 건너뛰세요."}, [65]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [66]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [67]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [68]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [69]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [70]={hint="악령의 숲에 있는 에리단 블루윈드에게 은백색 발톱 11개와 강철나무 심장 1개를 가져가야 합니다.", tag="선택사항", desc="따로 돌아가야 하며 근처에 다른 목표가 없습니다. 바쁘면 건너뛰어도 됩니다."}, [71]={npc="에리단 블루윈드", tgt="에리단 블루윈드", tag="선택사항"}, [72]={bind="아우버다인", desc="대기 중이면 걸어서 아스트라나르로 돌아가 아우버다인으로 날아가세요."}, [73]={to="Menethil Harbor", toA="{a:150}", from="아우버다인", desc="이 배는 도중에 사우스쇼어에 정박합니다. 메네실 항구에서 내리세요."}, [74]={to="아이언포지"}, [75]={npc="역사학자 카르닉", tgt="역사학자 카르닉"}, [76]={npc="역사학자 카르닉", tgt="역사학자 카르닉"}, [77]={npc="선임탐험가 마겔라스", tgt="선임탐험가 마겔라스"}, [78]={npc="왕실사학자 아케소누스", tgt="왕실사학자 아케소누스"}, [79]={npc="왕실사학자 아케소누스", tgt="왕실사학자 아케소누스"}, [80]={npc="왕실사학자 아케소누스", tgt="왕실사학자 아케소누스"}}},
    ["04-54"] = {steps={[1]={text="모건의 망루를 열었다면 아이언포지에서 바로 날아가세요. 열지 않았다면 레이크샤이어로 날아가 큰길을 따라 북쪽 불타는 평원으로 들어가세요. 모건의 망루는 입구 바로 옆에 있습니다.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [2]={nodeA="{a:2418}", node="Morgan's Vigil"}, [3]={npc="랄리우스", tgt="랄리우스"}, [4]={npc="랄리우스", tgt="랄리우스"}, [5]={npc="헬렌디스 리버혼", tgt="헬렌디스 리버혼", tag="파티가 있을 때, 선택사항"}, [6]={npc="팅키 스팀보일", tgt="팅키 스팀보일"}, [7]={npc="맥스워트 우버글린트", tgt="맥스워트 우버글린트"}, [8]={hint="불타는 평원, 타우릿산의 폐허에 있는 타우릿산 유물에서 정보를 얻어야 합니다. 정보를 발견하면 왕실사학자 아케소누스에게 돌아가야 합니다."}, [9]={hint="불타는 평원에 있는 맥스워트 우버글린트에게 서판 사본을 가져가야 합니다."}, [10]={hint="불자루일족 오우거마법사 15마리, 불자루 오우거 7마리, 불자루일족 투사 7마리를 처치한 후 랄리우스에게 돌아가야 합니다."}, [11]={hint="불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 새끼용의 정수 8개와 새끼용 속박장치 900을 가져가야 합니다."}, [12]={hint="검은 새끼용 15마리, 검은용혈족 10마리, 검은고룡족 4마리와 검은 비룡 1마리를 처치한 후, 헬렌디스 리버혼에게 돌아가야 합니다.", tag="파티가 있을 때, 선택사항", desc="검은용혈족과 검은 비룡은 51~53레벨 정예입니다."}, [13]={npc="키루스 테레펜터스", tgt="키루스 테레펜터스"}, [14]={npc="키루스 테레펜터스", tgt="키루스 테레펜터스"}, [15]={npc="팅키 스팀보일", tgt="팅키 스팀보일"}, [16]={npc="맥스워트 우버글린트", tgt="맥스워트 우버글린트"}, [17]={npc="랄리우스", tgt="랄리우스"}, [18]={npc="랄리우스", tgt="랄리우스", tag="선택사항"}, [19]={npc="헬렌디스 리버혼", tgt="헬렌디스 리버혼", tag="파티가 있을 때, 선택사항"}, [20]={npc="헬렌디스 리버혼", tgt="헬렌디스 리버혼"}, [21]={hint="우레망치 바위굴의 서쪽 어딘가에서 고르테쉬를 찾아 처치하고 고르테쉬의 가면을 얻어 불타는 평원에 있는 랄리우스에게 가져가야 합니다.", tag="선택사항"}, [22]={hint="랄리우스가 검은바위부족 메달 50개를 가져다 달라고 부탁했습니다. 불타는 평원에 있는 오크들에게서 메달을 구할 수 있는 가능성이 큽니다."}, [23]={npc="랄리우스", tgt="랄리우스"}, [24]={npc="랄리우스", tgt="랄리우스", tag="선택사항"}, [25]={to="Lakeshire", toA="{a:69}", desc="진정한 지도자를 하지 않는다면 바로 스톰윈드로 날아가고 다음 두 단계는 건너뛰세요."}, [26]={npc="집정관 솔로몬", tgt="집정관 솔로몬"}, [27]={npc="집정관 솔로몬", tgt="집정관 솔로몬"}, [28]={to="Stormwind"}, [29]={npc="우 셴", tgt="우 셴", tag="선택사항"}, [31]={npc="그레이슨 섀도브레이커 경", tgt="그레이슨 섀도브레이커 경", desc="서부 역병지대의 서리바람 야영지에서 완료하세요."}, [33]={npc="대영주 볼바르 폴드라곤", tgt="대영주 볼바르 폴드라곤"}, [34]={npc="대영주 볼바르 폴드라곤", tgt="대영주 볼바르 폴드라곤"}, [35]={npc="대영주 볼바르 폴드라곤", tgt="대영주 볼바르 폴드라곤"}, [36]={npc="대영주 볼바르 폴드라곤", tgt="대영주 볼바르 폴드라곤"}, [37]={npc="대영주 볼바르 폴드라곤", tgt="대영주 볼바르 폴드라곤", tag="선택사항"}, [38]={npc="단장 마티아스 쇼", tgt="단장 마티아스 쇼", tag="선택사항"}, [39]={npc="단장 마티아스 쇼", tgt="단장 마티아스 쇼", tag="선택사항"}, [40]={npc="단장 마티아스 쇼", tgt="단장 마티아스 쇼", tag="선택사항"}, [41]={npc="단장 마티아스 쇼", tgt="단장 마티아스 쇼", tag="선택사항"}, [42]={npc="포고꾼 굿맨", tgt="포고꾼 굿맨"}, [43]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항"}, [44]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항"}, [45]={hint="저주받은 땅에 있는 지옥멧돼지 7마리를 처치하고 호드 영웅의 넋에게 돌아가야 합니다.", tag="선택사항"}, [46]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항"}, [47]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항"}, [48]={hint="저주받은 땅에서 어둠의혈맹 숙련사제, 이교도, 암살단원을 각 20명씩 해치우고 호드 영웅의 넋에게 돌아가야 합니다.", tag="선택사항"}, [49]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항"}, [50]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="파티가 있을 때, 선택사항"}, [51]={hint="호드 영웅의 넋에게 가라앉은 사원에 있는 트롤들에게서 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 빼앗아 각 2개씩 가져가야 합니다.", tag="파티가 있을 때, 선택사항"}, [52]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="파티가 있을 때, 선택사항"}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", toA="{a:348}", desc="서리바람 야영지를 열었다면 바로 날아가고 다음 단계는 건너뛰세요. 비행 지도에 맹금의 봉우리가 없으면 사우스쇼어로 날아가 동부 내륙지 때와 같은 길로 동쪽 맹금의 봉우리까지 달려가세요."}, [2]={text="맹금의 봉우리에서 북쪽 산길을 따라 서부 역병지대 남동쪽 모퉁이(65.30, 86.80)로 들어간 뒤, 길을 따라 서쪽 서리바람 야영지까지 가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [3]={nodeA="{a:3197}", node="Chillwind Camp"}, [4]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [5]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [6]={hint="서부 역병지대에 있는 대사제 텔다니스에게 앞잡이의 스컬지석 20개를 모아 가져가야 합니다."}, [7]={npc="대사제 텔다니스", tgt="대사제 텔다니스"}, [8]={npc="대사제 텔다니스", tgt="대사제 텔다니스"}, [9]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [10]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트", tag="파티가 있을 때, 선택사항", desc="퀘스트를 완료하면 힘의 돌을 얻습니다."}, [11]={hint="아쉬람 발러피스트에게 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 각 2개씩 가져가야 합니다.", tag="파티가 있을 때, 선택사항", desc="퀘스트를 완료하면 힘의 돌을 얻습니다."}, [12]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트", tag="파티가 있을 때, 선택사항", desc="퀘스트를 완료하면 힘의 돌을 얻습니다."}, [13]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [14]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [15]={npc="은빛장교 퓨어하트", tgt="은빛장교 퓨어하트"}, [16]={npc="은빛장교 퓨어하트", tgt="은빛장교 퓨어하트"}, [17]={npc="은빛장교 퓨어하트", tgt="은빛장교 퓨어하트"}, [18]={npc="은빛장교 퓨어하트", tgt="은빛장교 퓨어하트", desc="편지 배달 퀘스트입니다. 하이잘 산 입구 근처에서 제출하세요."}, [19]={npc="플린트 섀도모어", tgt="플린트 섀도모어", tag="선택사항"}, [20]={npc="플린트 섀도모어", tgt="플린트 섀도모어", tag="선택사항"}, [21]={hint="슬픔의 언덕에 있는 해골 타작꾼 10마리와 걸신들린 구울 10마리를 처치해야 합니다."}, [22]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [23]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [24]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [25]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [26]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [27]={hint="신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다."}, [28]={hint="서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수도 있습니다. 빈 펠스톤 농장 병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}, [29]={npc="스컬지 가마솥", npcObj=true}, [30]={npc="스컬지 가마솥", npcObj=true}, [31]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [32]={npc="재니스의 소포", npcObj=true}, [33]={npc="재니스의 소포", npcObj=true}, [34]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [35]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [36]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [37]={hint="서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 지닌 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}, [38]={npc="스컬지 가마솥", npcObj=true}, [39]={npc="스컬지 가마솥", npcObj=true}, [40]={npc="달슨 부인의 일기", npcObj=true, desc="가마솥 옆 헛간에 있는 일지입니다."}, [41]={hint="퀘스트 목표를 완료하세요."}, [42]={npc="달슨 부인의 일기", npcObj=true}, [43]={npc="간이화장실", npcObj=true, desc="일기를 읽은 뒤 떠도는 해골을 찾으세요. 변소를 열면 농부가 나타납니다."}, [44]={hint="획득처: 떠도는 해골"}, [45]={npc="간이화장실", npcObj=true}, [46]={npc="잠긴 사물함", npcObj=true, desc="변소 주변을 먼저 정리하세요. 보관함을 열면 바로 제출할 수 있습니다."}, [47]={hint="획득처: 농부 달슨"}, [48]={npc="잠긴 사물함", npcObj=true}, [49]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [50]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [51]={npc="너대니얼 두마", tgt="너대니얼 두마"}, [52]={hint="서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}, [53]={npc="스컬지 가마솥", npcObj=true}, [54]={npc="스컬지 가마솥", npcObj=true}, [55]={npc="멀그리스 딥리버", tgt="멀그리스 딥리버"}, [56]={hint="역병에 걸린 늑대 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다."}, [57]={npc="멀그리스 딥리버", tgt="멀그리스 딥리버"}, [58]={npc="멀그리스 딥리버", tgt="멀그리스 딥리버"}, [59]={hint="오염된 불곰 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다."}, [60]={npc="멀그리스 딥리버", tgt="멀그리스 딥리버"}, [61]={npc="멀그리스 딥리버", tgt="멀그리스 딥리버"}, [62]={text="길을 따라 이 지점까지 달려가세요."}, [63]={text="맹금의 봉우리 여관에서 귀환석 위치를 설정하세요(13.80, 41.60).", bindA="{a:348}"}, [64]={npc="코르텔로의 보물", npcObj=true, tag="선택사항", desc="보물은 동부 내륙지 동쪽 해안에 있어 지도 전체를 가로질러야 합니다. 완료한 뒤 귀환석으로 돌아가세요."}, [65]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="맹금의 봉우리에서 북쪽 산길을 따라 서부 역병지대로 들어간 뒤, 동쪽으로 톤드로릴 강을 건너 동부 역병지대로 가세요. 티리온 폴드링은 입구 옆 오두막에 있습니다."}, [2]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [3]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [4]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [5]={hint="새끼 역병사냥개 20마리, 역병사냥개 5마리와 광포한 역병사냥개 5마리를 처치하십시오. 임무를 완수하면 티리온 폴드링에게 돌아가야 합니다."}, [6]={hint="역병박쥐 30마리를 처치한 후 티리온 폴드링에게 돌아가야 합니다."}, [7]={hint="부근에서 청소부구더기와 걸신들린 청소부구더기를 찾아 처치하고 청소부구더기 고기덩어리 15개를 모은 후 티리온 폴드링에게 돌아가야 합니다."}, [8]={npc="파멜라 레드패스", tgt="파멜라 레드패스"}, [9]={npc="파멜라 레드패스", tgt="파멜라 레드패스"}, [10]={hint="파멜라의 인형을 찾아야 합니다.", desc="다로우샤이어 폐가에서 머리, 왼쪽, 오른쪽 세 부분을 주워 오른쪽 클릭으로 합치세요."}, [11]={npc="파멜라 레드패스", tgt="파멜라 레드패스"}, [12]={npc="파멜라 레드패스", tgt="파멜라 레드패스"}, [13]={npc="파멜라 레드패스", tgt="파멜라 레드패스"}, [14]={npc="공작 니콜라스 즈바른호프", tgt="공작 니콜라스 즈바른호프"}, [15]={node="희망의 빛 예배당"}, [16]={npc="카를린 레드패스", tgt="카를린 레드패스"}, [17]={npc="카를린 레드패스", tgt="카를린 레드패스", tag="선택사항"}, [18]={npc="관리인 알렌", tgt="관리인 알렌"}, [19]={hint="15명의 다로우샤이어 주민들의 원혼을 자유롭게 하고 카를린 레드패스에게 돌아가야 합니다.", tag="선택사항", desc="따로 돌아가야 하며 근처에 다른 목표가 없습니다. 바쁘면 건너뛰어도 됩니다."}, [20]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [21]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [22]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [23]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [24]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [25]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [26]={hint="동부 역병지대의 최남쪽에 있는 지하 납골당으로 가서 탤런의 망치를 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다."}, [27]={hint="잴다르를 처치하고 그 증거로 머리카락을 희망의 빛 예배당에 있는 관리인 알렌에게 가져가야 합니다."}, [28]={npc="찢어진 두루마리", npcObj=true}, [29]={hint="동부 역병지대에서 \"블라이트콜러\"와 실종된 SI:7 요원들에 대한 단서를 찾아야 합니다. SI:7 배지를 찾게 되면 서리바람 야영지에 있는 플린트 섀도모어에게 가져가야 합니다.", tag="선택사항"}, [30]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [31]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [32]={npc="관리인 알렌", tgt="관리인 알렌"}, [33]={npc="카를린 레드패스", tgt="카를린 레드패스", tag="선택사항"}}},
    ["04-53"] = {steps={[1]={to="Southshore", toA="{a:271}", desc="서리바람 야영지나 맹금의 봉우리를 경유합니다. 비행 지도에 사우스쇼어가 없으면 평소처럼 스톰윈드로 날아가 항구에서 배를 타고 아우버다인으로 가세요."}, [2]={to="아우버다인", from="Southshore", fromA="{a:271}", desc="사우스쇼어 선착장에서 바로 아우버다인행 배를 탈 수 있어 스톰윈드로 날아가 배를 갈아타는 것보다 빠릅니다. 스톰윈드로 날아간다면 스톰윈드 항구에서 배를 타세요."}, [3]={to="Everlook", toA="{a:2255}"}, [4]={hint="여명의 설원에 있는 도노바 스노우덴이 눈사태일족 길잡이 8마리, 눈사태일족 보초 8마리, 눈사태일족 토템술사 8마리를 처치해달라고 요청했습니다."}, [5]={hint="살파가 눈사태일족 주술사 8마리, 눈사태일족 보초 8마리, 눈사태일족 펄볼그 8마리를 처치해달라고 부탁했습니다. 살파는 여명의 설원에 있는 나무구렁 요새의 입구 바로 밖에 있습니다."}, [6]={npc="빈 화주 시험관", npcObj=true, tag="떨어지면 수락", desc="눈사태일족 펄볼그가 빈 화주 시험관을 떨어뜨립니다. 주운 뒤 오른쪽 클릭으로 퀘스트를 받으세요. 아직 나오지 않았다면 펄볼그를 계속 잡으세요."}, [7]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [8]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="드랍될 때만 진행"}, [9]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [10]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [11]={npc="도노바 스노우덴", tgt="도노바 스노우덴", desc="검은속삭임 협곡 탐험은 다음 지점에서 하이잘 산으로 들어가는 길에 완료되며, 여명의 설원으로 돌아가 달의 숲으로 가기 전에 제출하세요. 여명의 설원으로 돌아가 달의 숲으로 가기 전에 제출하세요."}, [12]={hint="여명의 설원에서 달빛 깃든 깃털을 10개 모아서 루테란 마을의 에릴라스 엠버스카이에게 가져와야 합니다."}, [13]={npc="살파", tgt="살파"}, [14]={npc="마른가지 가마솥", npcObj=true}, [15]={npc="마른가지 가마솥", npcObj=true}, [16]={to="Rut'theran Village", toA="{a:702}", desc="마른가지 가마솥에서 남쪽으로 걸어 갈퀴가지 숲 비행 지점(62.49, 24.24)에서 출발하세요. 아우버다인에서 갈아탑니다."}, [17]={npc="에렐라스 앰버스카이", tgt="에렐라스 앰버스카이"}, [18]={npc="에렐라스 앰버스카이", tgt="에렐라스 앰버스카이"}, [19]={npc="다린 라이트윈드", tgt="다린 라이트윈드"}, [20]={to="Everlook", toA="{a:2255}"}, [21]={npc="하를로 위글즈워스", tgt="하를로 위글즈워스"}, [22]={npc="하를로 위글즈워스", tgt="하를로 위글즈워스", tag="선택사항", desc="마을 안에서 대화만 하는 퀘스트입니다. 후속 퀘스트는 정예 거인을 잡아야 하니 받지 마세요."}, [23]={npc="의술사 마우아리", tgt="의술사 마우아리", tag="선택사항"}, [24]={npc="우미 럼플스니커", tgt="우미 럼플스니커", desc="도노바 쪽에서 돌아와 남쪽으로 출발하기 전에 설인을 잡으세요."}, [25]={npc="윈드 나이트체이서", tgt="윈드 나이트체이서"}, [26]={npc="윈드 나이트체이서", tgt="윈드 나이트체이서"}, [27]={npc="야론 스톤셰이퍼", tgt="야론 스톤셰이퍼"}, [28]={npc="야론 스톤셰이퍼", tgt="야론 스톤셰이퍼"}, [29]={npc="야론 스톤셰이퍼", tgt="야론 스톤셰이퍼"}, [30]={npc="야론 스톤셰이퍼", tgt="야론 스톤셰이퍼"}, [31]={hint="야론의 곡괭이를 사용해 귀족 유물 조각 4개를 찾아 동부 역병지대에 있는 아우로라 스카이콜러에 갖다주어야 합니다."}, [32]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [33]={hint="두꺼운 설인 모피 10개를 모아 눈망루 마을에 있는 우미 럼플스니커에게 갖다주어야 합니다."}, [34]={npc="우미 럼플스니커", tgt="우미 럼플스니커"}, [35]={npc="우미 럼플스니커", tgt="우미 럼플스니커", tag="선택사항", desc="뿔은 동굴 안의 맹렬한 얼음엉겅퀴설인과 덩치큰 얼음엉겅퀴설인만 드랍하며 드랍률이 낮습니다. 경험치를 더 채우고 싶을 때 진행하세요."}, [36]={hint="눈망루 마을에 있는 우미 럼플스니커에게 온전한 설인 뿔 2개를 가져가야 합니다.", tag="선택사항"}, [37]={npc="우미 럼플스니커", tgt="우미 럼플스니커", tag="선택사항", desc="후속 퀘스트는 운고로와 가젯잔까지 가야 하니 받지 마세요."}, [38]={npc="부서진 상자", npcObj=true}, [39]={npc="부서진 상자", npcObj=true}, [40]={npc="야론의 짐마차", npcObj=true}, [41]={npc="야론의 짐마차", npcObj=true}, [42]={hint="눈 속에서 야론의 보급품을 회수한 다음, 야론이 찾는 아뮬렛을 훔친 올빼미야수들을 찾아야 합니다."}, [43]={npc="란샬라", tgt="란샬라"}, [44]={npc="란샬라", tgt="란샬라"}, [45]={hint="엘룬의 제단을 여는 과정에서 란샬라를 보호해야 합니다. 성공하면 루테란 마을에 있는 에렐라스 앰버스카이에게 발견한 내용을 보고해야 합니다."}}},
    ["04-57"] = {danger={[1]="Ghansurok(61레벨 정예 키메라)은 오염된 무궁화부터 케이레나의 작업장 일대(약 x55~62.5, y61.5~72.2)를 순찰합니다. 덤불을 칠 때와 작업장으로 돌아갈 때 위치를 먼저 확인하세요.", [2]="씁쓸한 셀라스트루스(57레벨 정예)가 오염된 무궁화 일대를 돌아다니니 덤불을 칠 때 주의하세요.", [3]="뼈 더미는 58레벨 정예 슬라임을 소환합니다. 파티가 없다면 두 번째로 클릭하지 마세요."}, grind={[1]={note="지옥피 흉터 북쪽 구간입니다. Felflick의 퀘스트는 모두 여기서 처치합니다."}}, supply={[1]={}}, steps={[1]={text="란샬라에서 남쪽 검은속삭임 협곡 (59.82, 74.25)으로 들어가 협곡을 따라 서쪽 끝까지 가면 하이잘 산입니다. 협곡 입구에는 정예 서리 거인, 안에는 정예 악마가 있으니 길을 따라 멈추지 말고 가세요.", tag="이 비행 지점을 아직 열지 않았다면 처음에는 걸어가야 합니다"}, [2]={hint="도노바 스노우덴의 지시를 따라 탐색을 한 후 되돌아오십시오.", desc="하이잘 산으로 협곡을 지나가면 완료되므로 따로 돌아갈 필요가 없습니다. 퀘스트 로그에 완료로 표시되면 인정됩니다."}, [3]={text="하이잘 산 남동쪽 모서리로 들어가 길을 따라 서쪽으로 가세요."}, [4]={npc="퀸투스 웨인워스", tgt="퀸투스 웨인워스"}, [5]={npc="퀸투스 웨인워스", tgt="퀸투스 웨인워스"}, [6]={npc="떨어져 나온 톱니바퀴", npcObj=true, desc="길가 바닥의 톱니바퀴입니다. 오른쪽 클릭으로 주워 퀘스트를 받으세요."}, [7]={npc="케타라스", tgt="케타라스", tag="선택사항", desc="이전에 악령의 숲에서 이 퀘스트를 받았을 때만 제출하세요."}, [8]={npc="케타라스", tgt="케타라스"}, [9]={npc="케타라스", tgt="케타라스"}, [10]={npc="케타라스", tgt="케타라스"}, [11]={npc="케타라스", tgt="케타라스"}, [12]={npc="케타라스", tgt="케타라스"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="케타라스", tgt="케타라스"}, [16]={npc="케타라스", tgt="케타라스"}, [17]={npc="케타라스", tgt="케타라스"}, [18]={npc="케타라스", tgt="케타라스"}, [19]={hint="획득처: 하이잘 수사슴, Predatory Hyjal Stag"}, [20]={hint="망가진 쇠뇌와 망가진 투석기, 망가진 비행기 주변에 마력 깃든 씨앗을 심어야 합니다.", desc="노포, 투석기, 비행기계 잔해는 각각 하나로 세며 세 곳 모두에 심어야 합니다. 은둔자의 동굴 밖 비탈에서 찾으세요."}, [21]={npc="케타라스", tgt="케타라스"}, [22]={npc="케타라스", tgt="케타라스"}, [23]={npc="케타라스", tgt="케타라스"}, [24]={hint="유해를 케타라스의 사당에 묻어야 합니다."}, [25]={npc="케타라스", tgt="케타라스"}, [26]={npc="케타라스", tgt="케타라스"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="길을 따라 서쪽으로 가세요. 비행 지점은 고목 정령 초소 옆에 있습니다."}, [28]={npc="프락시누스", tgt="프락시누스"}, [29]={npc="히아신스", tgt="히아신스"}, [30]={npc="히아신스", tgt="히아신스"}, [31]={npc="사일렌", tgt="사일렌", tag="파티가 있을 때, 선택사항", desc="목표는 57레벨 정예입니다. 혼자 이길 수 없다면 수락하지 마세요."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼"}, [34]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼"}, [35]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼", desc="나중에 눈망루 마을에 가면 Nami에게서 부품을 받으세요."}, [36]={hint="오염된 기슭 작업장에 있는 케이레나 스프링위스퍼를 위해 오염된 관목 15개를 파괴해야 합니다.", desc="같은 무궁화 덤불이 지혈 잎사귀도 떨어뜨리니 두 퀘스트를 함께 하세요. 상자를 전달할 때 작업장에서 제출하세요."}, [37]={hint="하이잘 산기슭에 있는 오염된 관목에서 푸른 잎 12개를 채집해야 합니다."}, [38]={hint="씁쓸한 셀라스트루스를 찾아 처치한 후, 부서진 잎사귀를 갖고 사일렌에게 가야 합니다.", tag="파티가 있을 때, 선택사항"}, [39]={npc="히아신스", tgt="히아신스"}, [40]={npc="히아신스", tgt="히아신스"}, [41]={npc="사일렌", tgt="사일렌", tag="파티가 있을 때, 선택사항"}, [42]={npc="히아신스", tgt="히아신스"}, [43]={hint="처치: 프락시누스"}, [44]={npc="프락시누스", tgt="프락시누스"}, [45]={npc="프락시누스", tgt="프락시누스", tag="파티가 있을 때, 선택사항", desc="목표인 Sunderbark는 56레벨 정예 고대정령이니 파티가 있을 때 진행하세요. 파티가 없으면 건너뛰세요. 이후의 완료 단계는 자동으로 생략됩니다."}, [46]={npc="프락시누스", tgt="프락시누스"}, [47]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [48]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [49]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="처치: Ashen Acolyte", desc="메모는 같은 시종들이 떨어뜨리니 두 퀘스트를 함께 하세요."}, [53]={hint="획득처: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [58]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [59]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [60]={hint="획득처: 맹독 진흙괴물"}, [61]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [62]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [63]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Felflick", tgt="Felflick"}, [66]={npc="Felflick", tgt="Felflick"}, [67]={hint="획득처: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz"}, [68]={hint="처치: Brashann Grimdark"}, [69]={npc="Felflick", tgt="Felflick"}, [70]={npc="Felflick", tgt="Felflick"}, [71]={npc="Felflick", tgt="Felflick"}, [72]={npc="Bone Pile", npcObj=true, desc="흑마법사 뼈를 슬라임 웅덩이 옆 뼈 더미에 던지세요."}, [73]={npc="Bone Pile", npcObj=true, tag="파티가 있을 때, 선택사항", desc="58레벨 정예 수액괴물이 소환됩니다. 파티가 없으면 Amalgamated Marrow와 후속 퀘스트를 건너뛰세요."}, [74]={hint="처치: Awakened Fel Ash Slime", tag="파티가 있을 때, 선택사항"}, [75]={npc="벨리시안", tgt="벨리시안"}, [76]={npc="Felflick", tgt="Felflick", tag="파티가 있을 때, 선택사항"}, [77]={npc="Felflick", tgt="Felflick"}, [78]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [79]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [80]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [81]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations."}, [83]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [84]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀", desc="다음 지점에서 서쪽 세월숲에 제출하세요."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="파티가 있을 때, 선택사항", desc="동쪽 은둔자의 동굴로 돌아가는 길에 있습니다."}, [86]={npc="케타라스", tgt="케타라스"}, [87]={npc="케타라스", tgt="케타라스"}, [88]={npc="프락시누스", tgt="프락시누스", tag="파티가 있을 때, 선택사항"}, [89]={to="Everlook", toA="{a:2255}"}, [90]={npc="Nami", tgt="Nami", desc="후속 상자는 시간 제한이 있으니 달의 숲에서 돌아온 뒤에 수락하세요."}, [91]={npc="야론 스톤셰이퍼", tgt="야론 스톤셰이퍼", desc="눈망루 마을에서 큰길을 따라 서쪽으로 조금 가면 별똥별 마을입니다."}, [92]={text="별똥별 마을에서 길을 따라 남서쪽 온천으로 달려가 Donova를 찾으세요."}, [93]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [94]={to="달의 숲", desc="온천에서 눈망루 마을 비행 지점으로 달려 돌아가 날아가세요(달의 숲 비행 지점은 {s:04-49}에서 열었습니다). 나무구렁 평판이 이미 중립이라면 온천에서 북쪽 나무구렁 요새 입구(27.70, 34.50)로 달려가 동굴을 지나 달의 숲 출구로 나가는 편이 가깝습니다. 달의 숲 비행 지점을 열지 않았다면 이 길로 가서 도착하자마자 먼저 비행 지점을 여세요(48.10, 67.34). 중립에 못 미치면 공격받습니다. 드루이드는 달의 숲으로 순간이동을 바로 쓸 수 있으며, 도착한 뒤 일반 비행 지점(48.10, 67.34)을 열어야 돌아올 때 날아갈 수 있습니다. 달의 숲 비행 지점을 열지 않았다면 이 길로 가서 도착하자마자 먼저 비행 지점을 여세요(48.10, 67.34). 중립에 못 미치면 공격받습니다. 드루이드는 달의 숲으로 순간이동을 바로 쓸 수 있으며, 도착한 뒤 일반 비행 지점(48.10, 67.34)을 열어야 돌아올 때 날아갈 수 있습니다."}, [95]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [96]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [97]={npc="오로카이", tgt="오로카이"}, [98]={npc="오로카이", tgt="오로카이"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [101]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [102]={to="Everlook", toA="{a:2255}", desc="달의 숲의 일반 비행 지점(48.10, 67.34)에서 출발해 눈망루 마을에서 내려 상자를 받으세요."}, [103]={npc="Nami", tgt="Nami", desc="상자 안 배터리는 약 두 시간 뒤에 못 쓰게 되므로 비행 지점에서 바로 케이레나에게 전달하세요."}, [104]={to="Tainted Foothills", toA="{a:16853}", desc="비행 지점에서 곧장 북쪽 케이레나의 작업장으로 달려가 먼저 상자를 전달하세요."}}},
    ["04-58"] = {danger={[1]="Ghansurok(61레벨 정예 키메라)이 아비아나의 제단 동쪽을 순찰하니 하피를 처치할 때 주의하세요."}, supply={[1]={}, [2]={}}, steps={[1]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼", desc="비행 지점에서 곧장 북쪽 작업장으로 달려가 먼저 상자를 전달하세요."}, [2]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼"}, [3]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼", desc="재료는 북쪽 데이건의 호드 야영지 잔해에 있으니 나중에 지나갈 때 주우세요."}, [4]={npc="케타라스", tgt="케타라스", desc="작업장에서 남동쪽으로 달려 은둔자의 동굴로 돌아가세요."}, [5]={npc="케타라스", tgt="케타라스"}, [6]={npc="케타라스", tgt="케타라스"}, [7]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="은둔자의 동굴에서 북서쪽 아비아나의 제단으로 달려가세요."}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={hint="획득처: Wormwing Harpy, Wormwing Windwitch, Wormwing Ambusher"}, [13]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [14]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [15]={hint="획득처: Zarrat Wormwing"}, [16]={npc="Corrupted Growth", npcObj=true, desc="나무에 붙은 타락한 혹을 오른쪽 클릭해 퀘스트를 받으세요."}, [17]={hint="사용/수집: Corrupted Growth"}, [18]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [22]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀"}, [23]={npc="호기심 많은 까마귀", tgt="호기심 많은 까마귀", desc="북쪽 평온의 요람의 다리 위에서만 할 수 있으니 일단 가지고 가세요."}, [24]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="산기슭을 따라 서쪽으로 가세요."}, [25]={hint="Locate a sturdy branch capable of reaching Fenwick Togglespring."}, [26]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={hint="처치: Tree Branch"}, [29]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [30]={npc="Fenwick Tog