eth에서 남쪽으로 조금 가면 있으며, 하이잘 올빼미를 처치해도 떨어집니다. 모은 뒤 세월숲으로 돌아가세요."}, [121]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [122]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [123]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [124]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame"}, [125]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [126]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [127]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [128]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [129]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [130]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [131]={npc="Daythor Brellan", tgt="Daythor Brellan"}}},
    ["04-60"] = {danger={[1]="Ghansurok(61레벨 정예 키메라)이 케이레나의 작업장 남쪽 능선을 돌아다닙니다.", [2]="Mazzogore(60레벨 정예)가 데이건 남쪽을 순찰하니 사냥개를 처치할 때 피해 가세요.", [3]="Ve'han Talongrasp(60레벨 정예)가 놀드랏실 오두막을 지키고 있으니 교단원 퀘스트를 할 때 너무 가까이 가지 마세요."}, grind={[1]={mob="지옥군단병 보초", note="데이건 남쪽 절반입니다. 겸사겸사 버려진 보급품과 호드 잔해 재료를 주우세요."}, [2]={note="영원의 정상 동쪽의 교단 야영지입니다. 산 정상 퀘스트는 모두 여기서 처치합니다."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="길을 따라 동쪽으로 돌아가세요."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Witherbeard", tgt="Witherbeard"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Light the two bonfires in Dae'gun and return to Yashiro."}, [7]={text="남동쪽 모닥불을 켠 뒤 계속 남동쪽 Renalard까지 가세요. 먼저 영리한 생물을 제출하고 재와 여우 퀘스트를 받은 뒤, 돌아오는 길에 데이건을 한 번 더 정리하세요."}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Collect 8 Abandoned Supplies.", desc="퀘스트에서 받은 여우 털뭉치(Tuft of Fox Fur)로 악마를 유인한 뒤 버려진 보급품 8개를 줍세요. 보급품은 Renalard 옆에 있지 않습니다."}, [12]={hint="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."}, [13]={hint="획득처: Defiling Hound"}, [14]={hint="처치: 지옥수호병 파수꾼"}, [15]={hint="Fetch a pinch of Azgalor's Ashes from the ruins of Dae'gun on Mount Hyjal."}, [16]={hint="Enter Dae'gun and locate a high vantage point, then report details to Johun."}, [17]={npc="Yashiro", tgt="Yashiro", desc="데이건을 정리한 뒤 여기 Yashiro에게 돌아와 제출하세요."}, [18]={npc="Yashiro", tgt="Yashiro", tag="선택사항"}, [19]={hint="Fight your way through Dae'gun with Yashiro.", tag="파티가 있을 때, 선택사항", desc="길을 정리하는 Yashiro를 따라가세요. 마지막에 파멸의 수호병 자르쿨(Doomguard Xarkul)을 쓰러뜨리면 완료됩니다."}, [20]={npc="Yashiro", tgt="Yashiro", tag="선택사항", desc="이벤트가 끝나는 곳에서 Yashiro에게 제출하세요. 시작 지점이 아닐 수 있습니다."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="파티가 있을 때, 선택사항", desc="두 목표 모두 60레벨 정예 악마입니다. 파티가 없으면 건너뛰세요. 후속 퀘스트는 자동으로 생략됩니다."}, [23]={hint="처치: Bethra'zel the Feeble, Mazzogore", tag="파티가 있을 때, 선택사항"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="파티가 있을 때, 선택사항"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [26]={npc="Witherbeard", tgt="Witherbeard"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="남동쪽으로 가세요."}, [29]={nodeA="{a:16849}", node="Summit of Eternity", desc="Renalard에서 동쪽으로 산을 조금 올라가 페이란 엘서스 비행 지점을 여세요. 산 위로 가져온 몇 개를 먼저 제출해 퀘스트 로그를 줄이세요."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="선택사항", desc="이전에 운고로 분화구에서 이 퀘스트를 받았을 때만 제출하세요."}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="세벨리아", tgt="세벨리아", desc="편지 꾸러미는 곧 눈망루 마을에서 제출하고 이어서 우편 연계를 하세요."}, [34]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼", desc="영원의 정상에서 서쪽으로 산을 내려가 Renalard를 지나 남쪽 작업장으로 가세요. 산길로 갈 수 없다면 오염된 기슭으로 날아가 북쪽으로 달려가세요."}, [35]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼"}, [36]={hint="Turn the two gears and connect the two battery terminals on both sides of Kaylaena's Glaive Thrower."}, [37]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼"}, [38]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼", tag="파티가 있을 때, 선택사항", desc="끌어오는 Ghansurok는 61레벨 정예 키메라입니다."}, [39]={hint="Walk to the ridge south of Kaylaena's workshop and find a way to make a loud distracting commotion to draw the chimaera Ghansurok in range to be attacked.", tag="파티가 있을 때, 선택사항", desc="작업장 남쪽 절벽의 북과 상호작용해 키메라를 회전 칼날 투척기 사거리 안으로 끌어오면 NPC가 투척기를 조작해 공격합니다. 멀리 끌고 가서 억지로 싸우지 마세요."}, [40]={npc="케이레나 스프링위스퍼", tgt="케이레나 스프링위스퍼", tag="파티가 있을 때, 선택사항"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="작업장에서 남서쪽으로 조금 걸어 아비아나의 제단으로 가세요."}, [42]={npc="케타라스", tgt="케타라스", desc="성소에서 남동쪽으로 달려 은둔자의 동굴로 돌아가세요."}, [43]={npc="케타라스", tgt="케타라스"}, [44]={npc="케타라스", tgt="케타라스"}, [45]={npc="케타라스", tgt="케타라스"}, [46]={to="Everlook", toA="{a:2255}", desc="은둔자의 동굴에서 서쪽으로 달려 오염된 기슭 비행 지점에서 출발하세요."}, [47]={npc="여관주인 비지", tgt="여관주인 비지"}, [48]={npc="여관주인 비지", tgt="여관주인 비지"}, [49]={hint="Find 4 pieces of Missing Mail in the hills north of Everlook and bring it back to Innkeeper Vizzie.", desc="우편물은 눈망루 마을 밖 언덕에 흩어져 있으니 퀘스트 목록의 안내를 따라 찾으세요. 찾지 못하면 일단 건너뛰어도 됩니다."}, [50]={npc="여관주인 비지", tgt="여관주인 비지"}, [51]={npc="여관주인 비지", tgt="여관주인 비지", desc="우편은 하이잘 산 정상으로 가져가 제출하세요."}, [52]={to="Summit of Eternity", toA="{a:16849}", desc="오염된 기슭에서 갈아탑니다."}, [53]={npc="세벨리아", tgt="세벨리아"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [57]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [58]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [59]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [62]={hint="Find thorn seeds in the forests at the summit of Mount Hyjal and bring them back to Tiala Whitemane."}, [63]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", desc="북쪽, 서쪽, 남쪽 바위는 각각 하나로 세며 세 곳 모두 가야 합니다."}, [64]={hint="Use the Staff of the Mountain on 10 members of the Blackthorne Pact on the Summit of Eternity to remove their wards and then kill them.", desc="같은 교단원이 광기 종결과 뒤틀린 도구에도 해당되니 먼저 지팡이를 쓰고 처치해 세 퀘스트를 함께 하세요."}, [65]={hint="처치: Blackthorne Cultist, Blackthorne Adept"}, [66]={hint="획득처: Blackthorne Cultist, Blackthorne Outrunner, Blackthorne Adept"}, [67]={hint="획득처: Mountain Squallclimber, 야생숨결 키메로크"}, [68]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [69]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [70]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [71]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [72]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp."}, [73]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [74]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [75]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="수락한 뒤 먼저 Marn Euhorn에게 가서 정화의 바람을 제출하고 아키몬드의 사면(Archimonde's Pardon)을 받으세요. 두 퀘스트는 같은 길에 하세요."}, [76]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [77]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [78]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", desc="공터에서 아이템으로 불러내지 말고 뿌리 아래에 원래 있는 소형 정령을 해방하세요. 아키몬드의 사면과 같은 길에 하세요."}, [79]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains."}, [80]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={to="Rut'theran Village", toA="{a:702}", desc="오염된 기슭과 눈망루 마을에서 갈아탑니다."}, [84]={npc="에렐라스 앰버스카이", tgt="에렐라스 앰버스카이"}, [85]={npc="에렐라스 앰버스카이", tgt="에렐라스 앰버스카이"}, [86]={text="루테란 마을의 차원문으로 들어가 다르나서스로 가세요."}, [87]={npc="대드루이드 판드랄 스테그헬름", tgt="대드루이드 판드랄 스테그헬름"}, [88]={npc="마스렌길 베어워커", tgt="마스렌길 베어워커"}}},
    ["04-59"] = {name="서부 역병지대", steps={[1]={bindA="{a:348}", desc="귀환석이 아직 맹금의 봉우리에 설정되어 있고 사용할 수 있을 때만 쓰세요. 그렇지 않으면 배편으로 대체하세요. 차원문으로 루테란 마을로 돌아가 아우버다인으로 날아가고, 메네실 항구행 배를 타 사우스쇼어에서 내린 뒤 칠윈드 야영지로 날아가세요."}, [2]={to="Chillwind Camp", toA="{a:3197}", desc="이미 칠윈드 야영지에 있다면 건너뛰세요. 비행 지도에 칠윈드 야영지가 없다면 맹금의 봉우리에서 산길을 따라 북쪽 서부 역병지대로 들어간 뒤 서쪽 칠윈드 야영지까지 달려가세요."}, [3]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [4]={npc="플린트 섀도모어", tgt="플린트 섀도모어", tag="선택사항"}, [5]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [6]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [7]={npc="연금술사 알빙턴", tgt="연금술사 알빙턴"}, [8]={npc="연금술사 알빙턴", tgt="연금술사 알빙턴", desc="수락해야 뼈조각이 드랍되기 시작합니다. 슬픔의 언덕과 안돌할에서 해골을 잡을 때 함께 모으세요."}, [9]={npc="말레네 레드패스", tgt="말레네 레드패스"}, [10]={npc="말레네 레드패스", tgt="말레네 레드패스"}, [11]={hint="조셉의 결혼반지를 크로미에게 가져가야 합니다."}, [12]={hint="서부 역병지대에 서리바람 거점에 있는 연금술사 알빙턴에게 뼈조각 15개를 가져가야 합니다."}, [13]={npc="크로미", tgt="크로미"}, [14]={npc="크로미", tgt="크로미"}, [15]={npc="크로미", tgt="크로미"}, [16]={hint="안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다."}, [17]={hint="안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오."}, [18]={npc="크로미", tgt="크로미"}, [19]={npc="크로미", tgt="크로미"}, [20]={npc="크로미", tgt="크로미"}, [21]={hint="안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다."}, [22]={npc="크로미", tgt="크로미"}, [23]={npc="크로미", tgt="크로미"}, [24]={to="희망의 빛 예배당", desc="안도할에는 비행 지점이 없습니다. 먼저 남쪽 서리바람 야영지로 걸어 돌아가 날아가세요."}, [25]={npc="카를린 레드패스", tgt="카를린 레드패스"}, [26]={npc="카를린 레드패스", tgt="카를린 레드패스", tag="선택사항"}, [27]={npc="카를린 레드패스", tgt="카를린 레드패스"}, [28]={hint="동부 역병지대의 북동쪽에 있는 노스데일로 가서 실추된 명예의 상징을 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다."}, [29]={hint="첩보원 하메야를 처치해야 합니다. 지하 납골당 뒤의 흙무더기에서 그의 열쇠를 사용하십시오."}, [30]={npc="아우로라 스카이콜러", tgt="아우로라 스카이콜러"}, [31]={hint="동부 역병지대에 있는 흰개미집으로 가서 빈 흰개미 병을 사용해야 합니다. 역병지대 흰개미 100마리를 모아 서부 역병지대의 서리바람 야영지에 있는 너대니얼 두마에게 돌아가야 합니다."}, [32]={hint="희망의 빛 예배당에 있는 카를린 레드패스에게 호르구스의 해골과 부러진 마르두크의 검을 가져가야 합니다.", tag="선택사항", desc="따로 돌아가야 하며 근처에 다른 목표가 없습니다. 바쁘면 건너뛰어도 됩니다."}, [33]={npc="Mound of Dirt", npcObj=true}, [34]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [35]={npc="티리온 폴드링", tgt="티리온 폴드링"}, [36]={hint="카를린 레드패스에게 다빌의 성서와 레드패스의 방패를 가져가야 합니다."}, [37]={hint="서부 역병지대의 가론의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 가론의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}, [38]={npc="스컬지 가마솥", npcObj=true}, [39]={npc="스컬지 가마솥", npcObj=true}, [40]={npc="화가 렌프레이", tgt="화가 렌프레이"}, [41]={npc="대여사제 맥도널", tgt="대여사제 맥도널"}, [42]={npc="연금술사 알빙턴", tgt="연금술사 알빙턴", desc="후속 퀘스트는 스칼로맨스에 들어가야 하니 받지 마세요."}, [43]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [44]={npc="사령관 아쉬람 발러피스트", tgt="사령관 아쉬람 발러피스트"}, [45]={npc="너대니얼 두마", tgt="너대니얼 두마"}, [46]={npc="너대니얼 두마", tgt="너대니얼 두마"}, [47]={npc="흰개미 통", npcObj=true}, [48]={npc="흰개미 통", npcObj=true}, [49]={hint="북마루 벌목지에 역병지대 흰개미를 놓아준 다음 역병지대 흰개미 통을 가지고 서부 역병지대 서리바람 야영지에 있는 너대니얼 두마에게 돌아가야 합니다."}, [50]={npc="키르스타 딥섀도", tgt="키르스타 딥섀도"}, [51]={hint="붉은십자군 의무병 2명, 붉은십자군 사냥꾼 2명, 붉은십자군 마법사 2명, 붉은십자군 기사 2명을 처치하고 서부 역병지대에 있는 키르스타 딥섀도에게 돌아가야 합니다."}, [52]={npc="키르스타 딥섀도", tgt="키르스타 딥섀도"}, [53]={npc="키르스타 딥섀도", tgt="키르스타 딥섀도"}, [54]={hint="사냥꾼 래들리와 기병 드루겐을 처치하고 서부 역병지대에 키르스타 딥섀도에게 돌아가야 합니다."}, [55]={npc="키르스타 딥섀도", tgt="키르스타 딥섀도"}, [56]={npc="키르스타 딥섀도", tgt="키르스타 딥섀도"}, [57]={hint="하스글렌에 들어가 마을이 잘 보이는 높은 지대를 찾아 붉은십자군 병력 규모를 파악한 다음 서부 역병지대에 있는 키르스타 딥섀도에게 돌아가야 합니다.", desc="좌표는 대략적인 위치입니다. 입구와 탑 옆에 붉은십자군 경비병이 있으니 한 마리씩 끌어오세요."}, [58]={npc="키르스타 딥섀도", tgt="키르스타 딥섀도"}, [59]={npc="너대니얼 두마", tgt="너대니얼 두마"}, [60]={to="희망의 빛 예배당", desc="이미 서리바람 야영지에 있으니 바로 비행 조련사를 찾아가세요."}, [61]={npc="카를린 레드패스", tgt="카를린 레드패스", tag="선택사항"}, [62]={npc="카를린 레드패스", tgt="카를린 레드패스"}, [63]={to="아이언포지"}, [64]={npc="왕실사학자 아케소누스", tgt="왕실사학자 아케소누스"}, [65]={to="Stormwind"}, [66]={npc="왕실조사원 바스릴로", tgt="왕실조사원 바스릴로"}, [67]={npc="왕실조사원 바스릴로", tgt="왕실조사원 바스릴로"}, [68]={npc="올엠마", tgt="올엠마"}, [69]={to="Lakeshire", toA="{a:69}", tag="선택사항", desc="진정한 지도자 가 있을 때만 레이크샤이어에 가세요. 없으면 스톰윈드에서 모건의 망루로 바로 비행하세요."}, [70]={npc="집정관 솔로몬", tgt="집정관 솔로몬"}, [71]={npc="집정관 솔로몬", tgt="집정관 솔로몬"}, [72]={to="Morgan's Vigil", toA="{a:2418}"}, [73]={npc="치안대