    ["05-d13"] = {name="스트라솔룸", entrance="동부 역병지대 26.52, 10.36", steps={[1]={to="Chillwind Camp", toA="{a:3197}"}, [2]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [3]={hint="새끼 역병사냥개 20마리, 역병사냥개 5마리와 광포한 역병사냥개 5마리를 처치하십시오. 임무를 완수하면 티리온 폴드링에게 돌아가야 합니다.", tag="던전 선행"}, [4]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [5]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [6]={hint="역병박쥐 30마리를 처치한 후 티리온 폴드링에게 돌아가야 합니다.", tag="던전 선행"}, [7]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [8]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [9]={hint="부근에서 청소부구더기와 걸신들린 청소부구더기를 찾아 처치하고 청소부구더기 고기덩어리 15개를 모은 후 티리온 폴드링에게 돌아가야 합니다.", tag="던전 선행"}, [10]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [11]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [12]={hint="티리온 폴드링이 하려고 하는 말이 무엇인지 들어야 합니다.", tag="던전 선행"}, [13]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [14]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [15]={hint="동부 역병지대의 최남쪽에 있는 지하 납골당으로 가서 탤런의 망치를 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다.", tag="던전 선행"}, [16]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [17]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [18]={hint="동부 역병지대의 북동쪽에 있는 노스데일로 가서 실추된 명예의 상징을 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다.", tag="던전 선행"}, [19]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [20]={npc="티리온 폴드링", tgt="티리온 폴드링", tag="던전 선행"}, [21]={npc="화가 렌프레이", tgt="화가 렌프레이", tag="던전 선행"}, [22]={npc="화가 렌프레이", tgt="화가 렌프레이"}, [23]={text="칠윈드 야영지에서 동쪽으로 서부 역병지대를 지나 동부 역병지대로 들어간 뒤 길을 따라 북쪽 스트라솔름으로 가세요."}, [24]={text="스트라솔룸 입구"}, [25]={hint="역병지대의 북쪽, 스트라솔름에 있는 붉은십자군 성채로 가서 쌍둥이 달 그림을 찾으십시오.", desc="붉은십자군 구역의 붉은십자군 성채에서 두 달이 그려진 그림을 찾으세요. 가족과 사랑은 그 뒤에 숨겨져 있습니다."}, [26]={npc="티리온 폴드링", tgt="티리온 폴드링", desc="티리온 폴드링은 동부 역병지대 서쪽 강가의 오두막에 있습니다."}, [27]={text="스트라솔름을 나와 남동쪽 희망의 빛 예배당으로 가세요."}, [28]={to="아이언포지"}}},
