    [8414] = {n="악마 퇴치", d="서부 역병지대에 있는 대사제 텔다니스에게 앞잡이의 스컬지석 20개를 모아 가져가야 합니다.", tgo={{"해골 타작꾼", "해골 마술사", "해골 망나니", "해골 사형집행인", "해골 수행사제", "걸신들린 구울", "썩어가는 구울", "영혼없는 구울"}}},
